//! A JSON value with insertion-ordered objects, a parser whose errors read as
//! serde_json's do, and writers (compact, pretty, key-sorted) that format numbers
//! the way serde_json does (integers as integers, floats in shortest form).

use std::fmt::Write as _;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Num(Num),
    Str(String),
    Arr(Vec<Value>),
    Obj(Map),
}

impl Default for Value {
    fn default() -> Value {
        Value::Null
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Num {
    U(u64),
    I(i64),
    F(f64),
}

impl PartialEq for Num {
    fn eq(&self, other: &Num) -> bool {
        match (self, other) {
            (Num::U(a), Num::U(b)) => a == b,
            (Num::I(a), Num::I(b)) => a == b,
            (Num::F(a), Num::F(b)) => a == b,
            _ => false,
        }
    }
}

impl Num {
    pub fn as_f64(&self) -> f64 {
        match *self {
            Num::U(u) => u as f64,
            Num::I(i) => i as f64,
            Num::F(f) => f,
        }
    }
}

/// An object: keys in insertion order.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map {
    pub items: Vec<(String, Value)>,
}

impl Map {
    pub fn new() -> Map {
        Map { items: Vec::new() }
    }
    (digits, exp + 1)
}

/// Formats an f64 as serde_json (ryu) does.
pub fn fmt_f64(x: f64) -> String {
    if !x.is_finite() {
        return "null".to_string();
    }
    let mut out = String::new();
    if x.is_sign_negative() {
        out.push('-');
    }
    if x == 0.0 {
        out.push_str("0.0");
        return out;
    }
    let (digits, kk) = shortest_digits(x);
    let length = digits.len() as i32;
    let k = kk - length;
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in length..kk {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if length > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        if kk - 1 > 0 {
            out.push('+');
        }
        let _ = write!(out, "{}", kk - 1);
    }
    out
}

/// How serde's "invalid type" message shows a float (Rust's Display, with a `.0` for integers).
pub fn fmt_f64_display(x: f64) -> String {
    if x.is_finite() && x == x.trunc() && x.abs() < 1e16 {
        format!("{}.0", x as i64)
    } else {
        format!("{}", x)
    }
}

fn write_num(n: &Num, out: &mut String) {
    match n {
        Num::U(u) => {
            let _ = write!(out, "{}", u);
        }
        Num::I(i) => {
            let _ = write!(out, "{}", i);
        }
        Num::F(f) => out.push_str(&fmt_f64(*f)),
    }
}

//! Reading a project file into a project.

use crate::json::Value;
use crate::project::Project;

pub fn load(v: Value) -> Result<Project, String> {
    if !matches!(v, Value::Obj(_)) {
        return Err(format!("invalid type: {}, expected struct ProjectFile", v.kind_name()));
    }
    let mut p = Project::from_value(v);
    crate::cloud::load(&mut p)?;
    Ok(p)
}

