#!/usr/bin/env python3
"""Print each wall's placement and body profile from an IFC file, compactly."""
import re, sys
ents = {}
for line in open(sys.argv[1]):
    m = re.match(r'#(\d+)=(\w+)\((.*)\);$', line.strip())
    if m: ents[int(m.group(1))] = (m.group(2), m.group(3))
def pt(i):
    t, a = ents[i]
    return a.strip('()')
def poly(i):
    t, a = ents[i]
    ids = [int(x) for x in re.findall(r'#(\d+)', a)]
    return ' '.join('(' + pt(j) + ')' for j in ids)
for i, (t, a) in sorted(ents.items()):
    if t in ('IFCWALL', 'IFCWALLSTANDARDCASE'):
        args = a.split(',')
        place = int(args[5][1:]); shape = int(args[6][1:])
        tag = re.findall(r"'(\d+)'", a)
        lp = ents[place][1]; ax = int(re.findall(r'#(\d+)', lp)[1])
        axa = ents[ax][1]; ids = [int(x) for x in re.findall(r'#(\d+)', axa)]
        loc = pt(ids[0]); d = pt(ids[2]) if len(ids) > 2 else '-'
        print('WALL', tag[-1] if tag else '?', 'at', loc, 'dir', d)
        reps = [int(x) for x in re.findall(r'#(\d+)', ents[shape][1])]
        for r in reps:
            rt, ra = ents[r]
            items = [int(x) for x in re.findall(r'#(\d+)', ra)][1:]
            for it in items:
                it_t, it_a = ents[it]
                if it_t == 'IFCEXTRUDEDAREASOLID':
                    prof = int(re.findall(r'#(\d+)', it_a)[0])
                    pa = ents[prof][1]
                    pl = int(re.findall(r'#(\d+)', pa)[0])
                    print('   body', poly(pl), 'h', it_a.split(',')[-1])
                elif it_t == 'IFCPOLYLINE':
                    print('   axis', poly(it))
                else:
                    print('  ', it_t)

