    return s.rstrip('0')

def load(bimf, ifcf):
    bim = json.load(open(bimf))
    floors = [e for k, e in sorted(bim['elements'].items(), key=lambda kv: int(kv[0])) if e['category'] == 'floor' and e.get('slope')]
    ents = {}
    for line in open(ifcf):
        m = re.match(r'#(\d+)=(\w+)\((.*)\);$', line.strip())
        if m: ents[int(m.group(1))] = (m.group(2), m.group(3))
    tops = []
    for i, (t, a) in sorted(ents.items()):
        if t == 'IFCSLAB':
            shape = int(a.split(',')[6][1:])
            rep = int(re.findall(r'#(\d+)', ents[shape][1])[0])
            if 'Brep' not in ents[rep][1]: continue
            items = [int(x) for x in re.findall(r'#(\d+)', ents[rep][1])][1:]
            b = items[0]
            shell = int(re.findall(r'#(\d+)', ents[b][1])[0])
            faces = [int(x) for x in re.findall(r'#(\d+)', ents[shell][1])]
            fb = int(re.findall(r'#(\d+)', ents[faces[1]][1])[0])
            pl = int(re.findall(r'#(\d+)', ents[fb][1])[0])
            tops.append([ents[int(x)][1].strip('()') for x in re.findall(r'#(\d+)', ents[pl][1])])
    return list(zip(floors, tops))

def norm(dx, dy):
    L = math.sqrt(dx*dx + dy*dy); r = 1.0/L
    return dx*r, dy*r

def cands(e, p):
    th = math.radians(e['slope']); z0 = e.get('offset', 0.0)
    tail, head = e['arrow']
    u = norm(head[0]-tail[0], head[1]-tail[1])
    tn = math.tan(th); sn = math.sin(th); cs = math.cos(th)
    L = math.sqrt((head[0]-tail[0])**2 + (head[1]-tail[1])**2)
    out = {}
    out['tail'] = z0 + ((p[0]-tail[0])*u[0] + (p[1]-tail[1])*u[1]) * tn
    zh = z0 + L*tn
    out['head'] = zh + ((p[0]-head[0])*u[0] + (p[1]-head[1])*u[1]) * tn
    # plane through tail with normal, d form
    for nm, n in [('n', (-u[0]*sn, -u[1]*sn, cs))]:
        ln = math.sqrt(n[0]*n[0]+n[1]*n[1]+n[2]*n[2]); r = 1/ln
        nn = (n[0]*r, n[1]*r, n[2]*r)
        for nname, N in [(nm, n), (nm+'u', nn)]:
            for refn, ref in [('T', (tail[0], tail[1], z0)), ('H', (head[0], head[1], zh))]:
                d = N[0]*ref[0] + N[1]*ref[1] + N[2]*ref[2]
                out['plane'+nname+refn] = (d - N[0]*p[0] - N[1]*p[1]) / N[2]
                out['plane2'+nname+refn] = (d - (N[0]*p[0] + N[1]*p[1])) / N[2]
                out['plane3'+nname+refn] = -(N[0]*p[0] + N[1]*p[1] - d) / N[2]
    # absolute linear form
    a = tn*u[0]; b = tn*u[1]
    c = z0 - (a*tail[0] + b*tail[1])
    out['lin'] = a*p[0] + b*p[1] + c
    out['lin2'] = c + a*p[0] + b*p[1]
    out['lin3'] = (a*p[0] + b*p[1]) + c
    c2 = z0 - tn*(u[0]*tail[0] + u[1]*tail[1])
    out['lin4'] = tn*(u[0]*p[0] + u[1]*p[1]) + c2
    out['lin5'] = z0 + tn*(u[0]*p[0] + u[1]*p[1]) - tn*(u[0]*tail[0] + u[1]*tail[1])
    out['lin6'] = z0 + (tn*(u[0]*p[0] + u[1]*p[1]) - tn*(u[0]*tail[0] + u[1]*tail[1]))
    out['lin7'] = z0 + ((u[0]*p[0] + u[1]*p[1]) - (u[0]*tail[0] + u[1]*tail[1]))*tn
    return out

stats = {}
for i in range(1, len(sys.argv), 2):
    for e, top in load(sys.argv[i], sys.argv[i+1]):
        for k, p in enumerate(e['boundary']):
            for name, z in cands(e, p).items():
                ok = (fmt(p[0]) + ',' + fmt(p[1]) + ',' + fmt(z)) == top[k]
                stats.setdefault(name, [0, 0])[0 if ok else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]): print(k, 'ok', v[0], 'bad', v[1])

