                    m.points.push(p);
                    m.points.len() - 1
                }
            };
        }
        m.tris.push(idx);
    }
    m
}

/// Mirrors a mesh across its x axis (y to -y), its triangles turned to stay facing out.
pub fn mirror_y(m: &mut Mesh) {
    for p in m.points.iter_mut() {
        p.y = -p.y;
    }
    for t in m.tris.iter_mut() {
        t.swap(1, 2);
    }
}
