#!/usr/bin/env python3
"""Print each faceted brep's top loop (x,y,z) of an IFC file. usage: rings.py file.ifc [--z]"""
import re, sys
ents = {}
for line in open(sys.argv[1]):
    m = re.match(r'#(\d+)=(\w+)\((.*)\);$', line.strip())
    if m: ents[int(m.group(1))] = (m.group(2), m.group(3))
withz = '--z' in sys.argv
for i, (t, a) in sorted(ents.items()):
    if t == 'IFCFACETEDBREP':
        shell = int(re.findall(r'#(\d+)', a)[0])
        faces = [int(x) for x in re.findall(r'#(\d+)', ents[shell][1])]
        fb = int(re.findall(r'#(\d+)', ents[faces[1]][1])[0])
        pl = int(re.findall(r'#(\d+)', ents[fb][1])[0])
        pts = [ents[int(x)][1].strip('()') for x in re.findall(r'#(\d+)', ents[pl][1])]
        if withz:
            print('brep', len(faces), ' '.join('(' + p + ')' for p in pts))
        else:
            print('brep', len(faces), ' '.join('(' + ','.join(p.split(',')[:2]) + ')' for p in pts))
    if t in ('IFCROOF', 'IFCWALL', 'IFCSLAB'):
        print(t, a.split(',')[-2], a.split(',')[-1])

