    n1=(x0+w-t,y0+t); n2=(x0+t,y0+t)
    return [([A,B,n1,n2],[0,0,t,t]),([B,C,n1],[0,0,t]),([C,D,n2,n1],[0,0,t,t]),([D,A,n2],[0,0,t])]
