        N = cross(sub(P[j],P[i]), sub(P[k],P[i]))
        for r in set([i,j,k,0,1,2]):
            d = dot(N, P[r])
            name = 'N%d%d%d_d%d' % (i,j,k,r)
            out[name] = [(d - N[0]*p[0] - N[1]*p[1])/N[2] for p in P[:2]]
