#!/usr/bin/env python3
"""Rectangles (rotated or not): search the face-plane formula matching the observed signs of
every bottom-ring z that prints as zero."""
import json, math, re, sys, itertools

def load(bim, ifc):
    d = json.load(open(bim))
    roofs = [e for k, e in sorted(d['elements'].items(), key=lambda kv: int(kv[0])) if e['category'] == 'roof']
    ents = {}
    for line in open(ifc):
        m = re.match(r'#(\d+)=(\w+)\((.*)\);$', line.strip())
        if m: ents[int(m.group(1))] = (m.group(2), m.group(3))
    obs = []; cur = []
    for i, (t, a) in sorted(ents.items()):
        if t == 'IFCFACETEDBREP':
            shell = int(re.findall(r'#(\d+)', a)[0])
            faces = [int(x) for x in re.findall(r'#(\d+)', ents[shell][1])]
            fb = int(re.findall(r'#(\d+)', ents[faces[1]][1])[0])
            pl = int(re.findall(r'#(\d+)', ents[fb][1])[0])
            top = [int(x) for x in re.findall(r'#(\d+)', ents[pl][1])]
            n = len(top)
            bot = [top[0] - n + k for k in range(n)]
            zs = [ents[b][1].strip('()').split(',')[2] for b in bot]
            cur.append(zs)
        if t == 'IFCROOF':
            obs.append(cur); cur = []
    return roofs, obs

def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); r = 1.0/l
    return (v[0]*r, v[1]*r)
def sub(a, b): return (a[0]-b[0], a[1]-b[1])
def add(a, b): return (a[0]+b[0], a[1]+b[1])
def mul(a, k): return (a[0]*k, a[1]*k)
def dot(a, b): return a[0]*b[0] + a[1]*b[1]

def skeleton_rect(B, velmode):
    pts = [tuple(map(float, p)) for p in B]
    E = []
    for i in range(4):
        p, q = pts[i], pts[(i+1) % 4]
        d = norm(sub(q, p)); E.append((p, d, (-d[1], d[0])))
    vel = []
    for i in range(4):
        (_, d1, n1), (_, d2, n2) = E[(i-1) % 4], E[i]
        if velmode == 'solve':
            det = n1[0]*n2[1] - n1[1]*n2[0]
            vel.append(((n2[1] - n1[1]) / det, (n1[0] - n2[0]) / det))
        else:
            b = norm(add(n1, n2)); c = dot(b, n1); vel.append((b[0]/c, b[1]/c))
    ev = []
    for i in range(4):
        p, d, n = E[i]; u, v = vel[i], vel[(i+1) % 4]
        rate = dot(sub(v, u), d); L = dot(sub(pts[(i+1) % 4], p), d)
        ev.append(L / -rate if rate < 0 else float('inf'))
    t = min(ev)
    short = [i for i in range(4) if abs(ev[i] - t) < 1e-6]
    # node where edge i collapses: vertex i moved to t
    nodes = {i: add(pts[i], mul(vel[i], ev[i])) for i in short}
    L0 = math.dist(pts[0], pts[1]); L1 = math.dist(pts[1], pts[2])
    if len(short) == 4:
        return None
    if L1 <= L0:   # edges 1 and 3 short
        n1, n3 = nodes[1], nodes[3]
        rings = [[pts[0], pts[1], n1, n3], [pts[1], pts[2], n1], [pts[2], pts[3], n3, n1], [pts[3], pts[0], n3]]
    else:
        n0, n2 = nodes[0], nodes[2]
        rings = [[pts[0], pts[1], n0], [pts[1], pts[2], n2, n0], [pts[2], pts[3], n2], [pts[3], pts[0], n0, n2]]
    return E, rings, t

def candidates(E, i, ring, t, tn, s, c):
    a, d, n = E[i]
    out = {}
    N = (-n[0]*s, -n[1]*s, c)
    refs = {'a': (a, 0.0), 'b': (ring[1], 0.0), 'r2': (ring[2], t*tn), 'rl': (ring[-1], t*tn)}
    for rn, (rp, rz) in refs.items():
        d0 = N[0]*rp[0] + N[1]*rp[1] + N[2]*rz
        out['d_' + rn] = lambda p, d0=d0: (d0 - N[0]*p[0] - N[1]*p[1]) / N[2]
        out['d2_' + rn] = lambda p, d0=d0: (d0 - (N[0]*p[0] + N[1]*p[1])) / N[2]
        out['r_' + rn] = lambda p, rp=rp, rz=rz: rz - (N[0]*(p[0]-rp[0]) + N[1]*(p[1]-rp[1])) / N[2]
        out['g_' + rn] = lambda p, rp=rp, rz=rz: rz + dot(sub(p, rp), n) * tn
        g = mul(n, tn)
        c0 = rz - dot(g, rp)
        out['l_' + rn] = lambda p, g=g, c0=c0: dot(g, p) + c0
        out['l2_' + rn] = lambda p, g=g, c0=c0: c0 + dot(g, p)
    return out

score = {}
for bim, ifc in [(a + '.bimcraft', a + '.ifc') for a in sys.argv[1:]]:
    roofs, obs = load(bim, ifc)
    for e, o in zip(roofs, obs):
        th = math.radians(e['slope']); tn = math.tan(th); s = math.sin(th); c = math.cos(th)
        for velmode in ['solve', 'bisect']:
            sk = skeleton_rect(e['boundary'], velmode)
            if sk is None: continue
            E, rings, t = sk
            for i, ring in enumerate(rings):
                for name, f in candidates(E, i, ring, t, tn, s, c).items():
                    key = velmode + ':' + name
                    sc = score.setdefault(key, [0, 0])
                    for k, p in enumerate(ring):
                        want = o[i][k]
                        if want not in ('0.', '-0.'): continue
                        got = fmt(f(p))
                        sc[0] += got == want; sc[1] += 1
for k, v in sorted(score.items(), key=lambda kv: -kv[1][0] / max(1, kv[1][1]))[:15]:
    print(k, v)

