    for rn, (rp, rz) in refs.items():
        d0 = N[0]*rp[0] + N[1]*rp[1] + N[2]*rz
        out['d_' + rn] = lambda p, d0=d0: (d0 - N[0]*p[0] - N[1]*p[1]) / N[2]
        out['d2_' + rn] = lambda p, d0=d0: (d0 - (N[0]*p[0] + N[1]*p[1])) / N[2]
        out['r_' + rn] = lambda p, rp=rp, rz=rz: rz - (N[0]*(p[0]-rp[0]) + N[1]*(p[1]-rp[1])) / N[2]
