pub fn less_openings(ring: &[V2], openings: &[Vec<V2>]) -> Vec<Vec<V2>> {
    let mut cur = vec![ring.to_vec()];
    for o in openings {
        let (olo, ohi) = bbox(o);
        let mut hole = o.clone();
        if signed_area(&hole) < 0.0 {
            hole.reverse();
        }
        let mut next = Vec::new();
        for r in cur {
            let (lo, hi) = bbox(&r);
            if ohi.x < lo.x || olo.x > hi.x || ohi.y < lo.y || olo.y > hi.y {
                next.push(r);
                continue;
            }
            let mut rest = r;
            for k in 0..hole.len() {
                let a = hole[k];
                let d = hole[(k + 1) % hole.len()] - a;
                let (outside, inside) = split_ring(&rest, a, d);
                if outside.len() >= 3 && signed_area(&outside).abs() > 1e-6 {
                    next.push(outside);
                }
                rest = inside;
                if rest.len() < 3 || signed_area(&rest).abs() <= 1e-6 {
                    break;
                }
            }
        }
        cur = next;
    }
    cur
}

