impl Plane {
    pub fn z(&self, p: V2) -> f64 {
        match *self {
            Plane::Eave { nx, ny, dd, lev } => (dd - (nx * p.x + ny * p.y)) - lev,
            Plane::Flat { z } => z,
            Plane::Along { a, d, x0, z0, k } => z0 + ((p - a).dot(d) - x0) * k,
