#!/usr/bin/env python3
"""Print the faceted breps of an IFC file: points (index: coords) and faces as point indices.

usage: faces.py FILE.ifc [ELEMENT-NAME-SUBSTRING]
"""
import re, sys
s = open(sys.argv[1]).read()
ents = {}
for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M):
    ents[int(m.group(1))] = (m.group(2), m.group(3))
def refs(t):
    return [int(x) for x in re.findall(r'#(\d+)', t)]
for k, (cls, args) in sorted(ents.items()):
    if cls != 'IFCFACETEDBREP':
        continue
    shell = refs(args)[0]
    faces = refs(ents[shell][1])
    pts = []
    loops = []
    for f in faces:
        bounds = refs(ents[f][1])
        fl = []
        for b in bounds:
            bc, ba = ents[b]
            loop = refs(ba)[0]
            ids = refs(ents[loop][1])
            for i in ids:
                if i not in pts:
                    pts.append(i)
            fl.append(([pts.index(i) for i in ids], bc == 'IFCFACEOUTERBOUND'))
        loops.append(fl)
    print('BREP #%d' % k)
    for i, p in enumerate(sorted(pts)):
        pass
    order = sorted(pts)
    idx = {p: order.index(p) for p in pts}
    for p in order:
        print('  p%d #%d %s' % (idx[p], p, ents[p][1]))
    for fl in loops:
        print('  F', ' | '.join(('' if outer else 'H:') + ','.join('p%d' % idx[pts[i]] for i in ids) for ids, outer in fl))

