#!/usr/bin/env python3
"""Check whether the top triangles of a shaped slab's brep are Delaunay (empty circumcircles)."""
import re, sys, itertools
s = open(sys.argv[1]).read()
ents = {}
for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M):
    ents[int(m.group(1))] = (m.group(2), m.group(3))
def refs(t):
    return [int(x) for x in re.findall(r'#(\d+)', t)]
def coords(i):
    return tuple(float(x) for x in re.findall(r'-?[\d.]+(?:E[-+]?\d+)?', ents[i][1]))
for k, (cls, args) in sorted(ents.items()):
    if cls != 'IFCFACETEDBREP':
        continue
    faces = refs(ents[refs(args)[0]][1])
    tops = []
    for fi, f in enumerate(faces):
        loop = refs(ents[refs(ents[f][1])[0]][1])
        tops.append([coords(i) for i in loop])
    # top faces are every other face until the sides; take faces at even positions with 3 points
    tris = [t for i, t in enumerate(tops) if i % 2 == 0 and len(t) == 3]
    pts = sorted(set((p[0], p[1]) for t in tops for p in t))
    bad = 0
    for t in tris:
        (ax, ay, _), (bx, by, _), (cx, cy, _) = t
        for (px, py) in pts:
            if (px, py) in [(ax, ay), (bx, by), (cx, cy)]:
                continue
            m = [[ax - px, ay - py, (ax - px) ** 2 + (ay - py) ** 2],
                 [bx - px, by - py, (bx - px) ** 2 + (by - py) ** 2],
                 [cx - px, cy - py, (cx - px) ** 2 + (cy - py) ** 2]]
            det = (m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
                   - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
                   + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))
            if det > 1e-6:
                bad += 1
                print('  not delaunay:', t, 'contains', (px, py), det)
    print('BREP #%d: %d triangles, %d violations' % (k, len(tris), bad))

