#!/usr/bin/env python3
"""Find interior point sets whose Delaunay triangles sort differently by sorted triple and by
CCW-from-min order."""
import random, itertools, json, sys

def incircle(a, b, c, p):
    m = [[a[0] - p[0], a[1] - p[1]], [b[0] - p[0], b[1] - p[1]], [c[0] - p[0], c[1] - p[1]]]
    r = [x * x + y * y for x, y in m]
    return (m[0][0] * (m[1][1] * r[2] - r[1] * m[2][1]) - m[0][1] * (m[1][0] * r[2] - r[1] * m[2][0])
            + r[0] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))

def orient(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def delaunay(pts):
    n = len(pts)
    tris = []
    for i, j, k in itertools.combinations(range(n), 3):
        o = orient(pts[i], pts[j], pts[k])
        if abs(o) < 1e-9:
            continue
        if o < 0:
            j, k = k, j
        ok = True
        for q in range(n):
            if q in (i, j, k):
                continue
            if incircle(pts[i], pts[j], pts[k], pts[q]) > 1e-6:
                ok = False
                break
        if ok:
            tris.append((i, j, k))
    return tris

def ccw_from_min(t):
    i = t.index(min(t))
    return t[i:] + t[:i]

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
for trial in range(2000):
    inner = [(random.randrange(5, 75) * 100, random.randrange(5, 55) * 100) for _ in range(4)]
    pts = sorted(set([(0, 0), (8000, 0), (8000, 6000), (0, 6000)] + inner))
    tris = delaunay(pts)
    # degenerate (cocircular) sets give overlapping triangles: skip them
    area = sum(orient(pts[a], pts[b], pts[c]) for a, b, c in tris) / 2
    if abs(area - 48e6) > 1:
        continue
    a = sorted(tris, key=lambda t: tuple(sorted(t)))
    b = sorted(tris, key=ccw_from_min)
    if [tuple(sorted(t)) for t in a] != [tuple(sorted(t)) for t in b]:
        print(json.dumps([list(p) for p in inner]))
        print('sorted :', [ccw_from_min(t) for t in a])
        print('ccwmin :', [ccw_from_min(t) for t in b])
        break

