9	fn ring_of(v: Option<&Value>) -> Vec<V2> {
10	    let mut out = Vec::new();
11	    if let Some(a) = v.and_then(|x| x.as_arr()) {
12	        for p in a {
13	            if let Some(q) = p.as_arr() {
14	                if q.len() >= 2 {
15	                    out.push(v2(q[0].as_f64().unwrap_or(0.0), q[1].as_f64().unwrap_or(0.0)));
16	                }
17	            }
18	        }
19	    }
20	    out
21	}
