23	fn json_ring(r: &[V2]) -> String {
24	    let mut s = String::from("[");
25	    for (i, p) in r.iter().enumerate() {
26	        if i > 0 {
27	            s.push(',');
28	        }
29	        s.push('[');
30	        s.push_str(&crate::json::fmt_f64(p.x));
31	        s.push(',');
32	        s.push_str(&crate::json::fmt_f64(p.y));
33	        s.push(']');
34	    }
35	    s.push(']');
36	    s
37	}
