56	/// The plane of a sloped floor's top: rising `slope` degrees from the arrow's tail, where it is
57	/// at `z0`, toward its head.
58	#[derive(Clone, Copy, Debug)]
59	pub struct Slope {
60	    pub tail: V2,
61	    pub dir: V2,
62	    pub tan: f64,
63	    pub z0: f64,
64	    pub cos: f64,
65	}
66	
67	impl Slope {
68	    pub fn z(&self, p: V2) -> f64 {
69	        self.z0 + (p - self.tail).dot(self.dir) * self.tan
70	    }
71	}
72	
73	pub fn slope_of(e: &Value, z0: f64) -> Option<Slope> {
74	    let s = e.get("slope").and_then(|v| v.as_f64()).unwrap_or(0.0);
75	    if s == 0.0 {
76	        return None;
77	    }
78	    let arrow = ring_of(e.get("arrow"));
79	    if arrow.len() < 2 {
80	        return None;
81	    }
82	    let d = arrow[1] - arrow[0];
83	    if d.length() < 1e-9 {
84	        return None;
85	    }
86	    let r = s.to_radians();
87	    Some(Slope { tail: arrow[0], dir: d.normalize(), tan: r.tan(), z0, cos: r.cos() })
88	}
