91	    pub fn write_floor(&mut self, id: u64, e: &Value) {
92	        let pr = self.pr;
93	        let level = e.get("level").and_then(|v| v.as_str()).unwrap_or("").to_string();
94	        let tg = e.get("type").and_then(|v| v.as_str()).unwrap_or("").to_string();
95	        let tname = super::walls::lib_name(pr, &tg);
96	        let td = super::walls::type_data(pr, "floor", &tg);
97	        let t = td.and_then(|t| t.get("thickness")).and_then(|v| v.as_f64()).unwrap_or(200.0);
98	        let offset = e.get("offset").and_then(|v| v.as_f64()).unwrap_or(0.0);
99	        let boundary = ring_of(e.get("boundary"));
100	        let holes = rings_of(e.get("openings"));
101	        let structural = e.get("structural").and_then(|v| v.as_bool()).unwrap_or(false);
102	        let rel = self.storey_place(&level);
103	        let place = self.placement(rel, v3(0.0, 0.0, 0.0), None);
104	        self.placements.insert(id, place);
105	        let gross_area = signed_area(&boundary).abs();
106	        let holes_area: f64 = holes.iter().map(|h| signed_area(h).abs()).sum();
107	        let slope = slope_of(e, offset);
108	        let shape;
109	        let quantities: Vec<(&str, &str, f64)>;
110	        match slope {
111	            None => {
112	                let outer = self.closed_polyline(&boundary);
113	                let prof = if holes.is_empty() {
114	                    self.add(format!("IFCARBITRARYCLOSEDPROFILEDEF(.AREA.,$,#{})", outer))
115	                } else {
116	                    let inner: Vec<usize> = holes.iter().map(|h| self.closed_polyline(h)).collect();
117	                    self.add(format!("IFCARBITRARYPROFILEDEFWITHVOIDS(.AREA.,$,#{},({}))", outer, refs(&inner)))
118	                };
119	                let p = self.st.point3(0.0, 0.0, offset - t);
120	                let pos = self.add(format!("IFCAXIS2PLACEMENT3D(#{},$,$)", p));
121	                let solid = self.add(format!("IFCEXTRUDEDAREASOLID(#{},#{},#{},{})", prof, pos, self.up, real(t)));
122	                let rep = self.add(format!("IFCSHAPEREPRESENTATION(#{},'Body','SweptSolid',(#{}))", self.body, solid));
123	                shape = self.add(format!("IFCPRODUCTDEFINITIONSHAPE($,$,(#{}))", rep));
124	                let net = gross_area - holes_area;
125	                quantities = vec![
126	                    ("L", "Width", t),
127	                    ("L", "Perimeter", perimeter(&boundary)),
128	                    ("A", "GrossArea", gross_area / 1e6),
129	                    ("A", "NetArea", net / 1e6),
130	                    ("V", "GrossVolume", gross_area * t / 1e9),
131	                    ("V", "NetVolume", net * t / 1e9),
132	                ];
133	            }
134	            Some(sl) => {
135	                // plumb it is its thickness over the cosine of its slope
136	                let tv = t / sl.cos;
137	                let breps = self.sloped_breps(&boundary, &holes, &sl, tv);
138	                let rep = self.add(format!("IFCSHAPEREPRESENTATION(#{},'Body','Brep',({}))", self.body, refs(&breps)));
139	                shape = self.add(format!("IFCPRODUCTDEFINITIONSHAPE($,$,(#{}))", rep));
140	                let net = gross_area - holes_area;
141	                quantities = vec![("L", "Width", tv), ("V", "GrossVolume", gross_area * tv / 1e9), ("V", "NetVolume", net * tv / 1e9)];
142	            }
143	        }
144	        let name = st(&tname);
145	        let product = self.add(format!(
146	            "IFCSLAB('{}',$,{},$,{},#{},#{},'{}',.FLOOR.)",
147	            gid(e.get("guid").and_then(|g| g.as_str()).unwrap_or("")),
148	            name,
149	            name,
150	            place,
151	            shape,
152	            id
153	        ));
154	        self.products.insert(id, product);
155	        self.finish(id, e, product, Some("Pset_SlabCommon"), structural);
156	        self.quantities("Qto_SlabBaseQuantities", product, &quantities);
157	        self.contain(&level, product);
158	        self.typed("IFCSLABTYPE", &tname, "$,$,$,$,$,$,.FLOOR.", product);
159	        if let Some(layers) = td.and_then(|t| t.get("layers")).and_then(|l| l.as_arr()).cloned() {
160	            if !layers.is_empty() {
161	                self.layer_usages.push(super::LayerUse {
162	                    kind: super::LayerKind::Slab,
163	                    type_key: format!("floor:{}", tg),
164	                    type_name: tname.clone(),
165	                    layers,
166	                    offset,
167	                    product,
168	                });
169	            }
170	        }
171	        self.cuttable.push((id, product, place, 0.0));
172	    }
