174	    /// A sloped slab: closed shells between its top plane and the same plane `tv` lower, its
175	    /// sides plumb.
176	    fn sloped_breps(&mut self, boundary: &[V2], holes: &[Vec<V2>], sl: &Slope, tv: f64) -> Vec<usize> {
177	        let _ = holes;
178	        let ring = boundary.to_vec();
179	        vec![self.prism_brep(&ring, &|p| sl.z(p) - tv, &|p| sl.z(p))]
180	    }
