182	    /// A closed faceted Brep over a ring in plan, between two heights at each corner: its
183	    /// bottom (turned down), its top, and a side for each edge.
184	    pub fn prism_brep(&mut self, ring: &[V2], bottom: &dyn Fn(V2) -> f64, top: &dyn Fn(V2) -> f64) -> usize {
185	        let n = ring.len();
186	        let b: Vec<usize> = ring.iter().map(|p| self.st.point3(p.x, p.y, bottom(*p))).collect();
187	        let t: Vec<usize> = ring.iter().map(|p| self.st.point3(p.x, p.y, top(*p))).collect();
188	        let mut faces = Vec::new();
189	        let rb: Vec<usize> = b.iter().rev().cloned().collect();
190	        faces.push(self.face(&rb));
191	        faces.push(self.face(&t));
192	        for i in 0..n {
193	            let j = (i + 1) % n;
194	            faces.push(self.face(&[b[i], b[j], t[j], t[i]]));
195	        }
196	        let shell = self.add(format!("IFCCLOSEDSHELL(({}))", refs(&faces)));
197	        self.add(format!("IFCFACETEDBREP(#{})", shell))
198	    }
