261	    /// Each shaft's opening through each floor, ceiling and roof its span reaches into and its
262	    /// outline overlaps, placed in that element's axes.
263	    pub fn write_shafts(&mut self) {
264	        let pr = self.pr;
265	        let shafts: Vec<u64> = pr.ids_of("shaft");
266	        for sid in shafts {
267	            let se = pr.el(sid).unwrap();
268	            let ring = ring_of(se.get("boundary"));
269	            let (base, top) = self.span_of(se);
270	            let hosts = self.cuttable.clone();
271	            for (hid, hprod, hplace, _) in hosts {
272	                let he = pr.el(hid).unwrap();
273	                let Some((z0, z1, outline)) = self.host_extent(hid, he) else { continue };
274	                if !(base < z1 && top > z0) {
275	                    continue;
276	                }
277	                if !rings_overlap(&ring, &outline) {
278	                    continue;
279	                }
280	                let hz = self.level_elev(he.get("level").and_then(|v| v.as_str()).unwrap_or(""));
281	                let oplace = self.placement(hplace, v3(0.0, 0.0, base - hz), None);
282	                let poly = self.closed_polyline(&ring);
283	                let prof = self.add(format!("IFCARBITRARYCLOSEDPROFILEDEF(.AREA.,$,#{})", poly));
284	                let solid =
285	                    self.add(format!("IFCEXTRUDEDAREASOLID(#{},#{},#{},{})", prof, self.origin, self.up, real(top - base)));
286	                let rep = self.add(format!("IFCSHAPEREPRESENTATION(#{},'Body','SweptSolid',(#{}))", self.body, solid));
287	                let shape = self.add(format!("IFCPRODUCTDEFINITIONSHAPE($,$,(#{}))", rep));
288	                let g = self.fresh();
289	                let op = self.add(format!(
290	                    "IFCOPENINGELEMENT('{}',$,'Shaft',$,$,#{},#{},'{}',.OPENING.)",
291	                    g, oplace, shape, sid
292	                ));
293	                let g = self.fresh();
294	                self.add(format!("IFCRELVOIDSELEMENT('{}',$,$,$,#{},#{})", g, hprod, op));
295	            }
296	        }
297	    }
