299	    /// The heights a floor, ceiling or roof spans, and its outline in plan.
300	    fn host_extent(&self, id: u64, e: &Value) -> Option<(f64, f64, Vec<V2>)> {
301	        let pr = self.pr;
302	        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
303	        let level = e.get("level").and_then(|v| v.as_str()).unwrap_or("");
304	        let lev = self.level_elev(level);
305	        let tg = e.get("type").and_then(|v| v.as_str()).unwrap_or("");
306	        let boundary = ring_of(e.get("boundary"));
307	        match cat {
308	            "floor" => {
309	                let t = super::walls::type_data(pr, "floor", tg).and_then(|t| t.get("thickness")).and_then(|v| v.as_f64()).unwrap_or(200.0);
310	                let off = e.get("offset").and_then(|v| v.as_f64()).unwrap_or(0.0);
311	                match slope_of(e, off) {
312	                    None => Some((lev + off - t, lev + off, boundary)),
313	                    Some(sl) => {
314	                        let tv = t / sl.cos;
315	                        let zs: Vec<f64> = boundary.iter().map(|p| sl.z(*p)).collect();
316	                        let lo = zs.iter().cloned().fold(f64::INFINITY, f64::min);
317	                        let hi = zs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
318	                        Some((lev + lo - tv, lev + hi, boundary))
319	                    }
320	                }
321	            }
322	            "ceiling" => {
323	                let t = super::walls::type_data(pr, "ceiling", tg).and_then(|t| t.get("thickness")).and_then(|v| v.as_f64()).unwrap_or(20.0);
324	                let off = e.get("offset").and_then(|v| v.as_f64()).unwrap_or(2600.0);
325	                Some((lev + off, lev + off + t, boundary))
326	            }
327	            _ => {
328	                let _ = id;
329	                self.roof_extent(id, e)
330	            }
331	        }
332	    }
