10	fn ring_of(v: Option<&Value>) -> Vec<V2> {
11	    let mut out = Vec::new();
12	    if let Some(a) = v.and_then(|x| x.as_arr()) {
13	        for p in a {
14	            if let Some(q) = p.as_arr() {
15	                if q.len() >= 2 {
16	                    out.push(v2(q[0].as_f64().unwrap_or(0.0), q[1].as_f64().unwrap_or(0.0)));
17	                }
18	            }
19	        }
20	    }
21	    out
22	}
