24	/// A piece of a roof: a ring in plan, the height of its underside at each corner and how
25	/// much higher its top is (plumb).
26	#[derive(Clone, Debug)]
27	pub struct Piece {
28	    pub ring: Vec<V2>,
29	    pub z: Vec<f64>,
30	    pub thick: f64,
31	    pub plane: Plane,
32	}
