34	/// The plane of a piece's underside: the height over its level at a point in plan.
35	#[derive(Clone, Copy, Debug)]
36	pub enum Plane {
37	    /// Rising from an eave: `(dd - (nx x + ny y)) - lev`.
38	    Eave { nx: f64, ny: f64, dd: f64, lev: f64 },
39	    /// Level.
40	    Flat { z: f64 },
41	    /// Along a line from `a` in `d`: `z0 + ((p - a)·d - x0) * k`.
42	    Along { a: V2, d: V2, x0: f64, z0: f64, k: f64 },
43	}
44	
45	impl Plane {
46	    pub fn z(&self, p: V2) -> f64 {
47	        match *self {
48	            Plane::Eave { nx, ny, dd, lev } => (dd - (nx * p.x + ny * p.y)) - lev,
49	            Plane::Flat { z } => z,
50	            Plane::Along { a, d, x0, z0, k } => z0 + ((p - a).dot(d) - x0) * k,
51	        }
52	    }
53	    /// The height over another reference, given the plane's level's elevation.
54	    pub fn z_over(&self, p: V2, own_lev: f64, reference: f64) -> f64 {
55	        match *self {
56	            Plane::Eave { nx, ny, dd, .. } => (dd - (nx * p.x + ny * p.y)) - reference,
57	            _ => self.z(p) + own_lev - reference,
58	        }
59	    }
60	}
