62	/// A ring clipped to a convex ring (counter-clockwise), one edge of it after another.
63	pub fn clip_ring(ring: &[V2], clip: &[V2]) -> Vec<V2> {
64	    let mut out = ring.to_vec();
65	    let n = clip.len();
66	    for i in 0..n {
67	        if out.is_empty() {
68	            break;
69	        }
70	        let a = clip[i];
71	        let b = clip[(i + 1) % n];
72	        let d = b - a;
73	        let inside = |p: V2| d.cross(p - a) >= -1e-9;
74	        let input = std::mem::take(&mut out);
75	        let m = input.len();
76	        let mut s = input[m - 1];
77	        for &e in &input {
78	            let ein = inside(e);
79	            let sin = inside(s);
80	            if ein {
81	                if !sin {
82	                    if let Some(x) = line_cross(s, e - s, a, d) {
83	                        out.push(x);
84	                    }
85	                }
86	                out.push(e);
87	            } else if sin {
88	                if let Some(x) = line_cross(s, e - s, a, d) {
89	                    out.push(x);
90	                }
91	            }
92	            s = e;
93	        }
94	    }
95	    out
96	}
