98	fn bbox(r: &[V2]) -> (V2, V2) {
99	    let mut lo = v2(f64::INFINITY, f64::INFINITY);
100	    let mut hi = v2(f64::NEG_INFINITY, f64::NEG_INFINITY);
101	    for p in r {
102	        lo = v2(lo.x.min(p.x), lo.y.min(p.y));
103	        hi = v2(hi.x.max(p.x), hi.y.max(p.y));
104	    }
105	    (lo, hi)
106	}
