108	/// A ring split by the line through `a` along `d`: the part to its right (outside, for a hole
109	/// running counter-clockwise) and the part to its left, each walked from the ring's start.
110	pub fn split_ring(ring: &[V2], a: V2, d: V2) -> (Vec<V2>, Vec<V2>) {
111	    let n = ring.len();
112	    let side = |p: V2| d.cross(p - a);
113	    let mut right = Vec::new();
114	    let mut left = Vec::new();
115	    for i in 0..n {
116	        let p = ring[i];
117	        let q = ring[(i + 1) % n];
118	        let sp = side(p);
119	        let sq = side(q);
120	        if sp <= 1e-9 {
121	            right.push(p);
122	        }
123	        if sp >= -1e-9 {
124	            left.push(p);
125	        }
126	        if (sp < -1e-9 && sq > 1e-9) || (sp > 1e-9 && sq < -1e-9) {
127	            let t = sp / (sp - sq);
128	            let x = p + (q - p) * t;
129	            right.push(x);
130	            left.push(x);
131	        }
132	    }
133	    (right, left)
134	}
