136	/// A face less the openings that reach it: split along each opening's edges in turn, the
137	/// parts outside each kept, what lies inside them all left out.
138	pub fn less_openings(ring: &[V2], openings: &[Vec<V2>]) -> Vec<Vec<V2>> {
139	    let mut cur = vec![ring.to_vec()];
140	    for o in openings {
141	        let (olo, ohi) = bbox(o);
142	        let mut hole = o.clone();
143	        if signed_area(&hole) < 0.0 {
144	            hole.reverse();
145	        }
146	        let mut next = Vec::new();
147	        for r in cur {
148	            let (lo, hi) = bbox(&r);
149	            if ohi.x < lo.x || olo.x > hi.x || ohi.y < lo.y || olo.y > hi.y {
150	                next.push(r);
151	                continue;
152	            }
153	            let mut rest = r;
154	            for k in 0..hole.len() {
155	                let a = hole[k];
156	                let d = hole[(k + 1) % hole.len()] - a;
157	                let (outside, inside) = split_ring(&rest, a, d);
158	                if outside.len() >= 3 && signed_area(&outside).abs() > 1e-6 {
159	                    next.push(outside);
160	                }
161	                rest = inside;
162	                if rest.len() < 3 || signed_area(&rest).abs() <= 1e-6 {
163	                    break;
164	                }
165	            }
166	        }
167	        cur = next;
168	    }
169	    cur
170	}
