172	/// What a roof by footprint is made of.
173	pub struct RoofGeom {
174	    pub pieces: Vec<Piece>,
175	    pub predefined: &'static str,
176	}
177	
178	impl<'a> Ex<'a> {
179	    /// The roof type's thickness.
180	    fn roof_thickness(&self, e: &Value) -> f64 {
181	        let tg = e.get("type").and_then(|v| v.as_str()).unwrap_or("");
182	        super::walls::type_data(self.pr, "roof", tg).and_then(|t| t.get("thickness")).and_then(|v| v.as_f64()).unwrap_or(300.0)
183	    }
184	
185	    /// A roof by footprint: its faces, each a piece over its ring.
186	    pub fn roof_geom(&self, e: &Value) -> RoofGeom {
187	        let thick = self.roof_thickness(e);
188	        let level = e.get("level").and_then(|v| v.as_str()).unwrap_or("");
189	        let lev = self.level_elev(level);
190	        let offset = e.get("offset").and_then(|v| v.as_f64()).unwrap_or(0.0);
191	        let slope = e.get("slope").and_then(|v| v.as_f64()).unwrap_or(30.0);
192	        let overhang = e.get("overhang").and_then(|v| v.as_f64()).unwrap_or(0.0);
193	        let mut outline = ring_of(e.get("boundary"));
194	        let mut courtyards: Vec<Vec<V2>> = Vec::new();
195	        if let Some(cs) = e.get("courtyards").and_then(|c| c.as_arr()) {
196	            for c in cs {
197	                let r = ring_of(Some(c));
198	                if r.len() >= 3 {
199	                    courtyards.push(r);
200	                }
201	            }
202	        }
203	        // the outline counter-clockwise and the courtyards clockwise, each edge keeping the
204	        // number it has as drawn (edge i from point i to the next)
205	        let mut given_of: Vec<usize> = Vec::new();
206	        let n0 = outline.len();
207	        if signed_area(&outline) < 0.0 {
208	            outline.reverse();
209	            given_of.extend((0..n0).map(|k| (2 * n0 - 2 - k) % n0));
210	        } else {
211	            given_of.extend(0..n0);
212	        }
213	        let mut base_k = n0;
214	        for c in courtyards.iter_mut() {
215	            let n = c.len();
216	            if signed_area(c) > 0.0 {
217	                c.reverse();
218	                given_of.extend((0..n).map(|k| base_k + (2 * n - 2 - k) % n));
219	            } else {
220	                given_of.extend((0..n).map(|k| base_k + k));
221	            }
222	            base_k += n;
223	        }
224	        if let Some(x) = e.get("extrusion") {
225	            // a profile drawn along a line, swept across to its left
226	            let line = ring_of(x.get("line"));
227	            let prof = ring_of(x.get("profile"));
228	            let from = x.get("from").and_then(|v| v.as_f64()).unwrap_or(0.0);
229	            let to = x.get("to").and_then(|v| v.as_f64()).unwrap_or(0.0);
230	            let mut pieces = Vec::new();
231	            if line.len() >= 2 && prof.len() >= 2 {
232	                let a = line[0];
233	                let d = (line[1] - line[0]).normalize();
234	                let n = d.perp();
235	                for k in 0..prof.len() - 1 {
236	                    let (p0, p1) = (prof[k], prof[k + 1]);
237	                    let ring = vec![a + d * p0.x + n * from, a + d * p1.x + n * from, a + d * p1.x + n * to, a + d * p0.x + n * to];
238	                    let z = vec![offset + p0.y, offset + p1.y, offset + p1.y, offset + p0.y];
239	                    let seg = p1 - p0;
240	                    let cos = (seg.x.abs() / seg.length()).max(1e-9);
241	                    let k = if seg.x.abs() > 1e-12 { seg.y / seg.x } else { 0.0 };
242	                    let plane = Plane::Along { a, d, x0: p0.x, z0: offset + p0.y, k };
243	                    pieces.push(Piece { ring, z, thick: thick / cos, plane });
244	                }
245	            }
246	            let predefined = match prof.len() {
247	                2 => "SHED_ROOF",
248	                3 => "GABLE_ROOF",
249	                _ => "FREEFORM",
250	            };
251	            return RoofGeom { pieces, predefined };
252	        }
253	        let n_out = outline.len();
254	        let n_all = n_out + courtyards.iter().map(|c| c.len()).sum::<usize>();
255	        if slope.abs() < 1e-9 {
256	            let mut pieces = Vec::new();
257	            pieces.push(Piece { z: vec![offset; outline.len()], ring: outline, thick, plane: Plane::Flat { z: offset } });
258	            return RoofGeom { pieces, predefined: "FLAT_ROOF" };
259	        }
260	        // each edge's slope, and its gables
261	        let mut gables: Vec<usize> = e
262	            .get("gables")
263	            .and_then(|g| g.as_arr())
264	            .map(|a| a.iter().filter_map(|x| x.as_u64().map(|u| u as usize)).collect())
265	            .unwrap_or_default();
266	        if e.get("gable").and_then(|g| g.as_bool()).unwrap_or(false) && n_out == 4 {
267	            let l0 = outline[0].distance(outline[1]);
268	            let l1 = outline[1].distance(outline[2]);
269	            if l1 <= l0 {
270	                gables.extend([1, 3]);
271	            } else {
272	                gables.extend([0, 2]);
273	            }
274	        }
275	        // in the skeleton's numbering
276	        let gables: Vec<usize> = (0..n_all).filter(|k| gables.contains(&given_of[*k])).collect();
277	        let slopes: Vec<f64> = (0..n_all)
278	            .map(|i| {
279	                let s = e
280	                    .get("slopes")
281	                    .and_then(|a| a.as_arr())
282	                    .and_then(|a| a.get(given_of[i]))
283	                    .and_then(|x| x.as_f64())
284	                    .unwrap_or(0.0);
285	                if s == 0.0 {
286	                    slope
287	                } else {
288	                    s
289	                }
290	            })
291	            .collect();
292	        let tans: Vec<f64> = slopes.iter().map(|s| s.to_radians().tan()).collect();
293	        let tan_min = tans
294	            .iter()
295	            .enumerate()
296	            .filter(|(i, _)| !gables.contains(i))
297	            .map(|(_, t)| *t)
298	            .fold(f64::INFINITY, f64::min);
299	        let tan_min = if tan_min.is_finite() { tan_min } else { slope.to_radians().tan() };
300	        let speeds: Vec<f64> = (0..n_all).map(|i| if gables.contains(&i) { 0.0 } else { tan_min / tans[i] }).collect();
301	        let mut rings = vec![outline.clone()];
302	        rings.extend(courtyards.iter().cloned());
303	        let faces = super::skeleton::faces(&rings, &speeds);
304	        // the eaves stay level, the base `overhang` in from them lowered by the slope
305	        let base = offset - overhang * slope.to_radians().tan();
306	        let openings = super::slabs::rings_of(e.get("openings"));
307	        let mut pieces = Vec::new();
308	        for (i, f) in faces.iter().enumerate() {
309	            let Some(f) = f else { continue };
310	            let ring: Vec<V2> = f.iter().map(|n| n.p).collect();
311	            // each corner on the plane of the face, in the building's heights: rising from its
312	            // eave at its slope
313	            let a = ring[0];
314	            let d = (ring[1] - ring[0]).normalize();
315	            let nrm = d.perp();
316	            let (nx, ny) = (-nrm.x * tans[i], -nrm.y * tans[i]);
317	            let dd = nx * a.x + ny * a.y + (lev + base);
318	            let cos = slopes[i].to_radians().cos();
319	            let plane = Plane::Eave { nx, ny, dd, lev };
320	            for part in less_openings(&ring, &openings) {
321	                let z: Vec<f64> = part.iter().map(|p| plane.z(*p)).collect();
322	                pieces.push(Piece { ring: part, z, thick: thick / cos, plane });
323	            }
324	        }
325	        let predefined = if gables.is_empty() { "HIP_ROOF" } else { "GABLE_ROOF" };
326	        RoofGeom { pieces, predefined }
327	    }
