329	    pub fn write_roof(&mut self, id: u64, e: &Value) {
330	        let pr = self.pr;
331	        let level = e.get("level").and_then(|v| v.as_str()).unwrap_or("").to_string();
332	        let tg = e.get("type").and_then(|v| v.as_str()).unwrap_or("").to_string();
333	        let tname = super::walls::lib_name(pr, &tg);
334	        let rel = self.storey_place(&level);
335	        let place = self.placement(rel, v3(0.0, 0.0, 0.0), None);
336	        self.placements.insert(id, place);
337	        let geom = self.roof_geom(e);
338	        let mut breps = Vec::new();
339	        for p in &geom.pieces {
340	            let zb = p.z.clone();
341	            let ring = p.ring.clone();
342	            let th = p.thick;
343	            let b: Vec<usize> = ring.iter().zip(zb.iter()).map(|(q, z)| self.st.point3(q.x, q.y, *z)).collect();
344	            let t: Vec<usize> = ring.iter().zip(zb.iter()).map(|(q, z)| self.st.point3(q.x, q.y, *z + th)).collect();
345	            breps.push(self.shell_between(&b, &t));
346	        }
347	        let rep = self.add(format!("IFCSHAPEREPRESENTATION(#{},'Body','Brep',({}))", self.body, refs(&breps)));
348	        let shape = self.add(format!("IFCPRODUCTDEFINITIONSHAPE($,$,(#{}))", rep));
349	        let name = st(&tname);
350	        let product = self.add(format!(
351	            "IFCROOF('{}',$,{},$,{},#{},#{},'{}',.{}.)",
352	            gid(e.get("guid").and_then(|g| g.as_str()).unwrap_or("")),
353	            name,
354	            name,
355	            place,
356	            shape,
357	            id,
358	            geom.predefined
359	        ));
360	        self.products.insert(id, product);
361	        self.finish(id, e, product, Some("Pset_RoofCommon"), false);
362	        self.contain(&level, product);
363	        let flat = geom.predefined == "FLAT_ROOF";
364	        let tail = if flat { "$,$,$,$,$,$,.FLAT_ROOF." } else { "$,$,$,$,$,$,.NOTDEFINED." };
365	        self.typed("IFCROOFTYPE", &tname, tail, product);
366	        if let Some(layers) = super::walls::type_data(pr, "roof", &tg).and_then(|t| t.get("layers")).and_then(|l| l.as_arr()).cloned() {
367	            if !layers.is_empty() {
368	                self.layer_usages.push(super::LayerUse {
369	                    kind: super::LayerKind::Roof,
370	                    type_key: format!("roof:{}", tg),
371	                    type_name: tname.clone(),
372	                    layers,
373	                    offset: 0.0,
374	                    product,
375	                });
376	            }
377	        }
378	        self.cuttable.push((id, product, place, 0.0));
379	    }
380	
381	    /// A closed faceted Brep between two rings of points written already: the bottom (turned
382	    /// down), the top, and a side for each edge.
383	    pub fn shell_between(&mut self, b: &[usize], t: &[usize]) -> usize {
384	        let n = b.len();
385	        let mut faces = Vec::new();
386	        let rb: Vec<usize> = b.iter().rev().cloned().collect();
387	        faces.push(self.face(&rb));
388	        faces.push(self.face(t));
389	        for i in 0..n {
390	            let j = (i + 1) % n;
391	            faces.push(self.face(&[b[i], b[j], t[j], t[i]]));
392	        }
393	        let shell = self.add(format!("IFCCLOSEDSHELL(({}))", refs(&faces)));
394	        self.add(format!("IFCFACETEDBREP(#{})", shell))
395	    }
396	}
