398	/// A surface a wall's top or base follows: over a ring in plan, a height (from the building's
399	/// datum, less a reference).
400	pub struct Follow {
401	    pub ring: Vec<V2>,
402	    pub plane: Plane,
403	    pub lev: f64,
404	    /// Added to the plane's height (a roof's or a floor's thickness, up or down).
405	    pub add: f64,
406	}
407	
408	impl<'a> Ex<'a> {
409	    /// The surfaces of an element a wall is attached to: a roof's underside (or top) piece by
410	    /// piece, a floor's top (or underside).
411	    pub fn follow_of(&self, g: &str, underside: bool) -> Vec<Follow> {
412	        let pr = self.pr;
413	        let Some(id) = pr.find_guid(g) else { return Vec::new() };
414	        let Some(e) = pr.el(id) else { return Vec::new() };
415	        let level = e.get("level").and_then(|v| v.as_str()).unwrap_or("");
416	        let lev = self.level_elev(level);
417	        match e.get("category").and_then(|c| c.as_str()) {
418	            Some("roof") => {
419	                let g = self.roof_geom(e);
420	                g.pieces
421	                    .into_iter()
422	                    .map(|p| {
423	                        let mut ring = p.ring;
424	                        if signed_area(&ring) < 0.0 {
425	                            ring.reverse();
426	                        }
427	                        Follow { ring, plane: p.plane, lev, add: if underside { 0.0 } else { p.thick } }
428	                    })
429	                    .collect()
430	            }
431	            Some("floor") => {
432	                let tg = e.get("type").and_then(|v| v.as_str()).unwrap_or("");
433	                let t = super::walls::type_data(pr, "floor", tg).and_then(|t| t.get("thickness")).and_then(|v| v.as_f64()).unwrap_or(200.0);
434	                let off = e.get("offset").and_then(|v| v.as_f64()).unwrap_or(0.0);
435	                let mut ring = ring_of(e.get("boundary"));
436	                if signed_area(&ring) < 0.0 {
437	                    ring.reverse();
438	                }
439	                match super::slabs::slope_of(e, off) {
440	                    Some(sl) => {
441	                        let tv = t / sl.cos;
442	                        let plane = Plane::Along { a: sl.tail, d: sl.dir, x0: 0.0, z0: off, k: sl.tan };
443	                        vec![Follow { ring, plane, lev, add: if underside { -tv } else { 0.0 } }]
444	                    }
445	                    None => vec![Follow { ring, plane: Plane::Flat { z: off }, lev, add: if underside { -t } else { 0.0 } }],
446	                }
447	            }
448	            _ => Vec::new(),
449	        }
450	    }
451	
452	    /// A wall attached to a roof or a floor: its outline (turned counter-clockwise) cut to each
453	    /// piece of what its top follows, each part a closed shell between its base and that piece.
454	    /// Points are in the wall's axes (`local`), heights over `reference`.
455	    pub fn attached_breps(&mut self, e: &Value, outline: &[V2], local: &dyn Fn(V2) -> V2, reference: f64, base_abs: f64, top_abs: f64) -> Option<Vec<usize>> {
456	        let top_g = e.get("attach_top").and_then(|v| v.as_str()).filter(|s| !s.is_empty()).map(|s| s.to_string());
457	        let base_g = e.get("attach_base").and_then(|v| v.as_str()).filter(|s| !s.is_empty()).map(|s| s.to_string());
458	        if top_g.is_none() && base_g.is_none() {
459	            return None;
460	        }
461	        let mut ring = outline.to_vec();
462	        ring.reverse();
463	        let tops = top_g.map(|g| self.follow_of(&g, true));
464	        let bases = base_g.map(|g| self.follow_of(&g, false));
465	        // the parts, each with what its top and its base follow
466	        let mut parts: Vec<(Vec<V2>, Option<usize>, Option<usize>)> = Vec::new();
467	        match &tops {
468	            Some(ts) => {
469	                for (i, f) in ts.iter().enumerate() {
470	                    let c = clip_ring(&ring, &f.ring);
471	                    if c.len() >= 3 && signed_area(&c).abs() > 1e-6 {
472	                        parts.push((c, Some(i), None));
473	                    }
474	                }
475	            }
476	            None => parts.push((ring.clone(), None, None)),
477	        }
478	        if let Some(bs) = &bases {
479	            let mut next = Vec::new();
480	            for (r, t, _) in parts {
