"""List the breps of an element's body: for each, the points of its first face (bottom) in plan.

usage: breps.py FILE.ifc ELEMENT-ID (the tag, e.g. 100005)
"""
import re, sys
s = open(sys.argv[1]).read()
ents = {}
for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M):
    ents[int(m.group(1))] = (m.group(2), m.group(3))
def refs(t):
    return [int(x) for x in re.findall(r'#(\d+)', t)]
tag = sys.argv[2]
