                shell = refs(ents[it][1])[0]
                faces = refs(ents[shell][1])
                bound = refs(ents[faces[1]][1])[0]
                loop = refs(ents[bound][1])[0]
                pts = [ents[i][1] for i in refs(ents[loop][1])]
                print('#%d top:' % it, ' '.join(p.replace('(', '').replace(')', '') for p in pts))

