#!/usr/bin/env python3
"""Simulate cutting a wall outline by the pieces of what it is attached to, progressively
(each piece splitting what is left along its edges), and print the parts in wall axes."""
import sys

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def split_ring(ring, a, d, eps=1e-9):
    n = len(ring)
    side = lambda p: cross(d, sub(p, a))
    right, left = [], []
    for i in range(n):
        p = ring[i]
        q = ring[(i + 1) % n]
        sp, sq = side(p), side(q)
        if sp <= eps:
            right.append(p)
        if sp >= -eps:
            left.append(p)
        if (sp < -eps and sq > eps) or (sp > eps and sq < -eps):
            t = sp / (sp - sq)
            x = (p[0] + (q[0] - p[0]) * t, p[1] + (q[1] - p[1]) * t)
            right.append(x)
            left.append(x)
    return right, left

def area(r):
    s = 0
    for i in range(len(r)):
        s += cross(r[i], r[(i + 1) % len(r)])
    return s / 2

def bbox(r):
    xs = [p[0] for p in r]
    ys = [p[1] for p in r]
    return min(xs), min(ys), max(xs), max(ys)

def progressive(outline, pieces):
    parts = []
    remaining = [outline]
    for pi, piece in enumerate(pieces):
        nxt = []
        lo = bbox(piece)
        for r in remaining:
            b = bbox(r)
            if lo[2] < b[0] or lo[0] > b[2] or lo[3] < b[1] or lo[1] > b[3]:
                nxt.append(r)
                continue
            rest = r
            for k in range(len(piece)):
                a = piece[k]
                d = sub(piece[(k + 1) % len(piece)], a)
                out, inn = split_ring(rest, a, d)
                if len(out) >= 3 and abs(area(out)) > 1e-6:
                    nxt.append(out)
                rest = inn
                if len(rest) < 3 or abs(area(rest)) <= 1e-6:
                    break
            if len(rest) >= 3 and abs(area(rest)) > 1e-6:
                parts.append((pi, rest))
        remaining = nxt
    return parts

def fmt(v):
    s = '%.6f' % (v + 0.0)
    s = s.rstrip('0')
    return s

pieces = [
    [(10000, 0), (12000, 3000), (10000, 6000)],
    [(10000, 0), (14000, 0), (12000, 3000)],
    [(10000, 6000), (12000, 3000), (14000, 6000)],
    [(12000, 3000), (14000, 0), (14000, 6000)],
    [(14000, 0), (16000, 3000), (14000, 6000)],
    [(14000, 0), (18000, 0), (16000, 3000)],
    [(14000, 6000), (16000, 3000), (18000, 6000)],
    [(16000, 3000), (18000, 0), (18000, 6000)],
]
rect = [(10000, 2900), (18000, 2900), (18000, 3100), (10000, 3100)]
o = (10000, 3000)
for rot in range(4):
    for rev in (False, True):
        r = rect[rot:] + rect[:rot]
        if rev:
            r = r[::-1]
        if area(r) < 0:
            continue
        print('rot', rot, 'rev', rev)
        for pi, part in progressive(r, pieces):
            print('  T%d' % pi, ' '.join('%s,%s' % (fmt(p[0] - o[0]), fmt(p[1] - o[1])) for p in part))

