    if var.isect == 'cross':
        r = sub(e, s)
        t = cross(sub(a, s), d) / cross(r, d)
        return (s[0] + r[0] * t, s[1] + r[1] * t)
    if var.isect == 'sides':
        t = ss / (ss - se)
        return (s[0] + (e[0] - s[0]) * t, s[1] + (e[1] - s[1]) * t)
    if var.isect == 'lerp':
        t = ss / (ss - se)
        return (s[0] * (1 - t) + e[0] * t, s[1] * (1 - t) + e[1] * t)
    if var.isect == 'online':
        # on the clip line: a + d u
        r = sub(e, s)
        u = cross(sub(s, a), r) / cross(d, r)
        return (a[0] + d[0] * u, a[1] + d[1] * u)
    raise ValueError

