6000.,0. 6000.,0. 6000.,0. 6066.666667,-100. 8000.,-100. 8000.,100. 6066.666667,100.""".split('\n')

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def fmt(v):
    v = v + 0.0
    s = '%.6f' % v
    s = s.rstrip('0')
    return s

