#!/usr/bin/env python3
"""Variants of progressive Sutherland-Hodgman splitting of a wall outline by the pieces it is
attached to, scored against parts the original wrote (several cases at once)."""
import itertools, sys

def fmt(v):
    v = v + 0.0
    s = '%.6f' % v
    return s.rstrip('0')

class V:
    def __init__(self, **kw):
        self.__dict__.update(kw)

def side_of(var, a, d, p):
    k = var.side
    if k == 'cross':
        return d[0] * (p[1] - a[1]) - d[1] * (p[0] - a[0])
    if k == 'nc':
        n = (-d[1], d[0])
        return (n[0] * p[0] + n[1] * p[1]) - (n[0] * a[0] + n[1] * a[1])
    l = (d[0] * d[0] + d[1] * d[1]) ** 0.5
    r = 1.0 / l
    u = (d[0] * r, d[1] * r)
    if k == 'unit':
        return u[0] * (p[1] - a[1]) - u[1] * (p[0] - a[0])
    if k == 'unitnc':
        n = (-u[1], u[0])
        return (n[0] * p[0] + n[1] * p[1]) - (n[0] * a[0] + n[1] * a[1])
    if k == 'unitdot':
        n = (-u[1], u[0])
        return n[0] * (p[0] - a[0]) + n[1] * (p[1] - a[1])
    raise ValueError(k)

def isect(var, s, e, a, d, ss, se):
    k = var.isect
    if k == 'sides':
        t = ss / (ss - se)
        return (s[0] + (e[0] - s[0]) * t, s[1] + (e[1] - s[1]) * t)
    if k == 'lerp2':
        t = ss / (ss - se)
        return (s[0] * (1 - t) + e[0] * t, s[1] * (1 - t) + e[1] * t)
    if k == 'sides_e':
        t = se / (se - ss)
        return (e[0] + (s[0] - e[0]) * t, e[1] + (s[1] - e[1]) * t)
    if k == 'cross':
        r = (e[0] - s[0], e[1] - s[1])
        den = r[0] * d[1] - r[1] * d[0]
        num = (a[0] - s[0]) * d[1] - (a[1] - s[1]) * d[0]
        t = num / den
        return (s[0] + r[0] * t, s[1] + r[1] * t)
    if k == 'online':
        r = (e[0] - s[0], e[1] - s[1])
        den = d[0] * r[1] - d[1] * r[0]
        num = (s[0] - a[0]) * r[1] - (s[1] - a[1]) * r[0]
        u = num / den
        return (a[0] + d[0] * u, a[1] + d[1] * u)
    raise ValueError(k)

def half(var, ring, a, d, keep_left):
    sides = [side_of(var, a, d, p) for p in ring]
    eps = var.eps
    if keep_left:
        inside = (lambda v: v >= -eps) if var.incl else (lambda v: v > -eps)
    else:
        inside = (lambda v: v <= eps) if var.incl else (lambda v: v < eps)
    out = []
    n = len(ring)
    for i in range(n):
        si = (i - 1) % n
        s, e = ring[si], ring[i]
        ss, se = sides[si], sides[i]
        if inside(se):
            if not inside(ss):
                out.append(isect(var, s, e, a, d, ss, se))
            out.append(e)
        elif inside(ss):
            out.append(isect(var, s, e, a, d, ss, se))
    return out

def area(r):
    return sum(r[i][0] * r[(i + 1) % len(r)][1] - r[i][1] * r[(i + 1) % len(r)][0] for i in range(len(r))) / 2

def bbox(r):
    xs = [p[0] for p in r]
    ys = [p[1] for p in r]
    return min(xs), min(ys), max(xs), max(ys)

def progressive(var, outline, pieces):
    parts = []
    remaining = [outline]
    for pi, piece in enumerate(pieces):
        nxt = []
        lo = bbox(piece)
        pc = piece[::-1] if var.cw else piece
        for r in remaining:
            b = bbox(r)
            if var.bbox and (lo[2] < b[0] or lo[0] > b[2] or lo[3] < b[1] or lo[1] > b[3]):
                nxt.append(r)
                continue
            rest = r
            for k in range(len(pc)):
                a = pc[k]
                bb = pc[(k + 1) % len(pc)]
                d = (bb[0] - a[0], bb[1] - a[1])
