                    nxt.append(out)
                rest = inn
                if len(rest) < 3 or abs(area(rest)) <= var.amin:
                    break
            if len(rest) >= 3 and abs(area(rest)) > var.amin:
                parts.append((pi, rest))
        remaining = nxt
    return parts

TRI4 = lambda x0, y0, x1, y1, cx, cy: [[(x0, y0), (cx, cy), (x0, y1)], [(x0, y0), (x1, y0), (cx, cy)], [(x0, y1), (cx, cy), (x1, y1)], [(cx, cy), (x1, y0), (x1, y1)]]
CASES = {
    'w1': (TRI4(0, 0, 8000, 6000, 4000, 3000), (0, 2000), [(0, 1900), (8000, 1900), (8000, 2100), (0, 2100)],
           """2533.333333,-100. 2800.,100. 0.,100. 0.,-100.
2800.,100. 2533.333333,-100. 5466.666667,-100. 5200.,100. 2800.,100.
5200.,100. 5200.,100. 5466.666667,-100. 8000.,-100. 8000.,100. 5200.,100."""),
