4000.,0. 4000.,0. 4000.,0. 4133.333333,100. 3866.666667,100.
4000.,0. 4133.333333,-100. 8000.,-100. 8000.,100. 4133.333333,100."""),
    'asset': ([
        [(10000, 0), (12000, 3000), (10000, 6000)],
        [(10000, 0), (14000, 0), (12000, 3000)],
        [(10000, 6000), (12000, 3000), (14000, 6000)],
        [(12000, 3000), (14000, 0), (14000, 6000)],
        [(14000, 0), (16000, 3000), (14000, 6000)],
        [(14000, 0), (18000, 0), (16000, 3000)],
        [(14000, 6000), (16000, 3000), (18000, 6000)],
        [(16000, 3000), (18000, 0), (18000, 6000)],
    ], (10000, 3000), [(10000, 2900), (18000, 2900), (18000, 3100), (10000, 3100)],
        """1933.333333,-100. 2000.,-0. 1933.333333,100. 0.,100. 0.,-100.
2000.,-0. 1933.333333,-100. 2066.666667,-100.
1955.555556,66.666667 2000.,0. 2000.,0. 2000.,0. 2066.666667,100. 1933.333333,100.
2000.,-0. 2022.222222,-33.333333 2022.222222,-33.333333 2066.666667,-100. 4000.,-100. 4000.,100. 2066.666667,100.
4000.,-100. 5933.333333,-100. 6000.,0. 5933.333333,100. 4000.,100.
6000.,0. 6000.,0. 5933.333333,-100. 6066.666667,-100.
6000.,0. 6000.,0. 6066.666667,100. 5933.333333,100.
6000.,0. 6000.,0. 6000.,0. 6066.666667,-100. 8000.,-100. 8000.,100. 6066.666667,100."""),
}

def run(var, rot, case):
    pieces, o, rect, exp = CASES[case]
    r = rect[rot:] + rect[:rot]
    try:
        parts = progressive(var, r, pieces)
    except ZeroDivisionError:
        return 0, []
    lines = [' '.join('%s,%s' % (fmt(p[0] - o[0]), fmt(p[1] - o[1])) for p in part) for _, part in parts]
    exp = exp.split('\n')
    score = sum(1 for a, b in zip(lines, exp) if a == b) - abs(len(lines) - len(exp))
    return score, lines

if __name__ == '__main__':
    cases = sys.argv[1:] or list(CASES)
    results = []
    dims = dict(side=['cross', 'nc', 'unit', 'unitnc', 'unitdot'], isect=['sides', 'lerp2', 'sides_e', 'cross', 'online'],
                outside=['comp', 'rev'], incl=[True, False], eps=[0.0, 1e-12, 1e-9, 1e-6], cw=[False, True],
                amin=[0.0, 1e-6, 1e-3, 1.0], bbox=[True, False])
    keys = list(dims)
    total = sum(len(CASES[c][3].split('\n')) for c in cases)
