grep -n "IFCWALL(" -B0 /workspace/assets/test_model_geometry/walls.ifc | cut -c1-80; python3 - << 'EOF'
import re
s=open('/workspace/assets/test_model_geometry/walls.ifc').read()
ents={}
for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M):
    ents[int(m.group(1))]=(m.group(2),m.group(3))
def refs(t): return [int(x) for x in re.findall(r'#(\d+)',t)]
for k,(c,a) in ents.items():
    if c in ('IFCWALL','IFCROOF','IFCDOOR','IFCWINDOW','IFCOPENINGELEMENT'):
        pl=refs(a)[0] if c!='IFCOPENINGELEMENT' else refs(a)[0]
        lp=ents[pl]; ax=ents[refs(lp[1])[-1]]
        r=refs(ax[1])
        print(c, a.split(',')[2], a.split(',')[7] if c=='IFCWALL' else '', 'rel', refs(lp[1])[0] if lp[1].startswith('#') else '$', 'at', ents[r[0]][1], 'dir', ents[r[2]][1] if len(r)>2 else '')
    if c=='IFCQUANTITYLENGTH' and "'Length'" in a: print('   ', a)
EOF

