        let base_offset = e.get("base_offset").and_then(|v| v.as_f64()).unwrap_or(0.0);
        let level_elev = self.level_elev(&w.level);
        let top = self.wall_top(e, level_elev + base_offset);
        let height = top - (level_elev + base_offset);
        let origin = w.start;
        let d = w.start_dir();
        let n = d.perp();
        let local = |p: V2| {
            let v = p - origin;
