/// One end of a wall seen from the node it is at: the direction into the wall and its faces
/// to the left and right of that direction.
#[derive(Clone, Copy, Debug)]
struct End {
    wall: usize,
    p: V2,
    u: V2,
    oleft: f64,
    oright: f64,
}

impl End {
    fn left_line(&self) -> (V2, V2) {
        (self.p + self.u.perp() * self.oleft, self.u)
    }
    fn right_line(&self) -> (V2, V2) {
        (self.p - self.u.perp() * self.oright, self.u)
    }
}

fn end_of(w: &Wall, i: usize, at_end: bool) -> End {
    if !at_end {
        End { wall: i, p: w.start, u: w.start_dir(), oleft: w.left, oright: w.right }
    } else {
        End { wall: i, p: w.end, u: -w.end_dir(), oleft: w.right, oright: w.left }
    }
}

