#!/usr/bin/env python3
"""Summarise stairs, ramps and their parts in an IFC file: flights (placement, risers, treads,
solids), landings (outline, depth)."""
import re, sys
s = open(sys.argv[1]).read()
ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
def refs(t):
    return [int(x) for x in re.findall(r'#(\d+)', t)]
def placement(lp):
    a = refs(ents[lp][1])
    ax = ents[a[-1]][1]
    r = refs(ax)
    at = ents[r[0]][1]
    d = ents[r[2]][1] if len(r) > 2 else '-'
    return at, d
for k, (c, a) in sorted(ents.items()):
    if c in ('IFCSTAIR', 'IFCRAMP'):
        print(c, a.split(',')[-2], a.split(',')[-1])
    if c in ('IFCSTAIRFLIGHT', 'IFCRAMPFLIGHT'):
        r = refs(a)
        at, d = placement(r[0])
        print('  ', c, 'at', at, 'dir', d, a.split(',', 8)[-1][:60])
        shape = r[1]
        for rep in refs(ents[shape][1]):
            for it in refs(ents[rep][1])[1:]:
                ci, ai = ents[it]
                if ci == 'IFCEXTRUDEDAREASOLID':
                    ri = refs(ai)
                    prof = ents[ri[0]]
                    pos = ents[ri[1]][1]
                    pt = ents[refs(pos)[0]][1]
                    depth = ai.split(',')[-1]
                    pp = refs(prof[1])
                    ctr = ents[refs(ents[pp[0]][1])[0]][1]
                    print('      tread', ctr, prof[1].split(',')[-2:], 'from', pt, 'depth', depth)
                elif ci == 'IFCFACETEDBREP':
                    shell = refs(ai)[0]
                    pts = []
                    for f in refs(ents[shell][1]):
                        for b in refs(ents[f][1]):
                            for p in refs(ents[refs(ents[b][1])[0]][1]):
                                if ents[p][1] not in pts:
                                    pts.append(ents[p][1])
                    print('      brep', ' '.join(pts))
    if c == 'IFCSLAB' and '.LANDING.' in a:
        r = refs(a)
        shape = r[1]
        for rep in refs(ents[shape][1]):
            for it in refs(ents[rep][1])[1:]:
                ci, ai = ents[it]
                if ci == 'IFCEXTRUDEDAREASOLID':
                    ri = refs(ai)
                    prof = ents[ri[0]]
                    poly = refs(prof[1])[0]
                    pts = [ents[p][1] for p in refs(ents[poly][1])]
                    pos = ents[ri[1]][1]
                    print('   LANDING', ' '.join(pts), 'from', ents[refs(pos)[0]][1], 'depth', ai.split(',')[-1])
                elif ci == 'IFCFACETEDBREP':
                    shell = refs(ai)[0]
                    pts = []
                    for f in refs(ents[shell][1]):
                        for b in refs(ents[f][1]):
                            for p in refs(ents[refs(ents[b][1])[0]][1]):
                                if ents[p][1] not in pts:
                                    pts.append(ents[p][1])
                    print('   LANDING brep', ' '.join(pts))

