#!/usr/bin/env python3
"""Summarise railings: placement, axis polyline, and each brep's corner points."""
import re, sys
s = open(sys.argv[1]).read()
ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
def refs(t):
    return [int(x) for x in re.findall(r'#(\d+)', t)]
only = sys.argv[2] if len(sys.argv) > 2 else None
for k, (c, a) in sorted(ents.items()):
    if c != 'IFCRAILING':
        continue
    tag = a.split(',')[7]
    if only and only not in tag:
        continue
    r = refs(a)
    lp = ents[r[0]][1]
    print('RAILING', tag, a.split(',')[2], 'placement rel', refs(lp)[0] if lp[0] == '#' else '$')
    for rep in refs(ents[r[1]][1]):
        ra = ents[rep][1]
        items = refs(ra)[1:]
        kind = ra.split(',')[1]
        for it in items:
            ci, ai = ents[it]
            if ci == 'IFCPOLYLINE':
                print('   axis', ' '.join(ents[p][1] for p in refs(ai)))
            elif ci == 'IFCFACETEDBREP':
                shell = refs(ai)[0]
                faces = refs(ents[shell][1])
                pts = []
                for f in faces[:2]:
                    for b in refs(ents[f][1]):
                        loop = refs(ents[b][1])[0]
                        pts.append(' '.join(ents[p][1] for p in refs(ents[loop][1])))
                print('   brep', len(faces), 'faces | bottom', pts[0], '| top', pts[1])

