def add(a, b):
    return (a[0] + b[0], a[1] + b[1])

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def mul(a, k):
    return (a[0] * k, a[1] * k)

def line_cross(a, d, b, e):
    den = cross(d, e)
    t = cross(sub(b, a), e) / den
    return add(a, mul(d, t))

def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2)
    return (v[0] * (1 / l), v[1] * (1 / l))

r = math.radians(90.0)
d = (math.cos(r), math.sin(r))
n = (-d[1], d[0])
w = 1000.0
off = w / 2 - 50
L = 840.0
hyps = {}
