    a = add(start, mul(n, -off))
    res['x_side_riser'] = line_cross(a, d, start, n)
    res['x_riser_side'] = line_cross(start, n, a, d)
    # side line from the right corner, along the edge
    res['x_edge_riser'] = line_cross(add(rc, mul(n, 50.0)), d, start, n)
