        print(c, a.split(',')[2], a.split(',')[7] if len(a.split(',')) > 7 else '', ents[r[0]][1], ents[r[2]][1] if len(r) > 2 else '')
    if c == 'IFCQUANTITYLENGTH' and ("'Length'" in a or "'Height'" in a):
        print('   ', a)

