472	/// The forms of a family's type for an element, each a mesh in the family's axes (a hosted
473	/// family's flipped as its element is).
474	pub fn meshes(pr: &Project, fam: &Value, type_name: &str, e: &Value, hosted: Option<Hosted>) -> Vec<Mesh> {
475	    let vals = all_values(pr, fam, type_name, e, hosted);
476	    let mirrored = hosted.is_none() && e.get("mirrored").and_then(|m| m.as_bool()).unwrap_or(false);
477	    let names: Vec<String> = vals.keys().cloned().collect();
478	    let forms = fam.get("forms").and_then(|f| f.as_arr()).cloned().unwrap_or_default();
479	    let mut out = Vec::new();
480	    for fo in &forms {
481	        if let Some(vis) = fo.get("visible") {
482	            let shown = match vis {
483	                Value::Bool(b) => *b,
484	                Value::Str(s) => match vals.get(s) {
485	                    Some(v) => v.num() != 0.0,
486	                    None => eval(s, &vals, &names).map(|x| x != 0.0).unwrap_or(true),
487	                },
488	                Value::Num(n) => n.as_f64() != 0.0,
489	                _ => true,
490	            };
491	            if !shown {
492	                continue;
493	            }
494	        }
495	        if fo.get("void").and_then(|v| v.as_bool()).unwrap_or(false) {
496	            continue;
497	        }
498	        let Some(mut tris) = prism(fo, &vals, &names) else { continue };
499	        if mirrored {
500	            for t in tris.iter_mut() {
501	                for p in t.iter_mut() {
502	                    p.y = -p.y;
503	                }
504	                t.swap(1, 2);
505	            }
506	        }
507	        let mut m = mesh_of(&tris);
508	        m.material = form_material(pr, fo, &vals);
509	        out.push(m);
510	    }
511	    out
512	}
