514	/// The name of the material a form is made of: a material parameter's value, or a material
515	/// named by GUID.
516	fn form_material(pr: &Project, fo: &Value, vals: &HashMap<String, Val>) -> Option<String> {
517	    let m = fo.get("material")?.as_str()?;
518	    let g = match vals.get(m) {
519	        Some(Val::S(s)) => s.clone(),
520	        _ => m.to_string(),
521	    };
522	    pr.lib_name(&g).or_else(|| {
523	        if pr.get("materials").and_then(|x| x.get(&g)).is_some() {
524	            Some(g.clone())
525	        } else {
526	            None
527	        }
528	    })
529	}
530	
531	/// Triangulates a simple ring, its corners counter-clockwise: ears clipped from the first
532	/// corner on.
533	pub fn ear_clip(ring: &[V2]) -> Vec<[usize; 3]> {
534	    let n = ring.len();
535	    let mut idx: Vec<usize> = (0..n).collect();
536	    let mut out = Vec::new();
537	    let mut k = 0usize;
538	    let mut guard = 0;
539	    while idx.len() >= 3 && guard < 10 * n * n + 10 {
540	        guard += 1;
541	        let m = idx.len();
542	        let i0 = idx[(k + m - 1) % m];
543	        let i1 = idx[k % m];
544	        let i2 = idx[(k + 1) % m];
545	        let (a, b, c) = (ring[i0], ring[i1], ring[i2]);
546	        let convex = (b - a).cross(c - b) > 0.0;
547	        let mut ok = convex || m == 3;
548	        if ok && m > 3 {
549	            for &j in &idx {
550	                if j == i0 || j == i1 || j == i2 {
551	                    continue;
552	                }
553	                if in_tri(ring[j], a, b, c) {
554	                    ok = false;
555	                    break;
556	                }
557	            }
558	        }
559	        if ok {
560	            out.push([i0, i1, i2]);
561	            idx.remove(k % m);
562	            if k >= idx.len() {
563	                k = 0;
564	            }
565	        } else {
566	            k = (k + 1) % m;
567	        }
568	    }
569	    out
570	}
571	
572	fn in_tri(p: V2, a: V2, b: V2, c: V2) -> bool {
573	    let d1 = (b - a).cross(p - a);
574	    let d2 = (c - b).cross(p - b);
575	    let d3 = (a - c).cross(p - c);
576	    d1 >= 0.0 && d2 >= 0.0 && d3 >= 0.0
577	}
578	
579	/// A form swept straight: its profile's caps (the far one first) and its sides.
580	fn prism(fo: &Value, vals: &HashMap<String, Val>, names: &[String]) -> Option<Vec<[V3; 3]>> {
581	    let plane = fo.get("plane").and_then(|p| p.as_str()).unwrap_or("xy");
582	    let from = size(fo.get("from"), vals, names);
583	    let to = size(fo.get("to"), vals, names);
584	    let mut ring: Vec<V2> = Vec::new();
585	    if let Some(pts) = fo.get("profile").and_then(|p| p.as_arr()) {
586	        for p in pts {
587	            let a = p.as_arr()?;
588	            ring.push(v2(size(a.first(), vals, names), size(a.get(1), vals, names)));
589	        }
590	    } else if let Some(c) = fo.get("circle") {
591	        let cc = c.get("centre").and_then(|x| x.as_arr()).cloned().unwrap_or_default();
592	        let cx = size(cc.first(), vals, names);
593	        let cy = size(cc.get(1), vals, names);
594	        let r = size(c.get("radius"), vals, names);
595	        let k = 32;
596	        for i in 0..k {
597	            let a = std::f64::consts::TAU * i as f64 / k as f64;
598	            ring.push(v2(cx + r * a.cos(), cy + r * a.sin()));
599	        }
600	    }
601	    if ring.len() < 3 {
602	        return None;
603	    }
604	    if signed_area(&ring) < 0.0 {
605	        ring.reverse();
606	    }
607	    let tris = ear_clip(&ring);
608	    let to3 = |p: V2, h: f64| -> V3 {
609	        match plane {
610	            "xz" => v3(p.x, h, p.y),
611	            "yz" => v3(h, p.x, p.y),
612	            _ => v3(p.x, p.y, h),
613	        }
614	    };
615	    // the triangles as written: the far cap's and the near cap's in turn, then the sides; a
616	    // profile in the xz plane faces the other way round its sweep, so all of them turn over
617	    let flip = plane == "xz";
618	    let mut written: Vec<[V3; 3]> = Vec::new();
619	    let mut tri = |w: &mut Vec<[V3; 3]>, a: V3, b: V3, c: V3| {
620	        if flip {
621	            w.push([a, c, b]);
622	        } else {
623	            w.push([a, b, c]);
624	        }
625	    };
626	    let n = ring.len();
627	    for t in &tris {
628	        tri(&mut written, to3(ring[t[0]], to), to3(ring[t[1]], to), to3(ring[t[2]], to));
629	        tri(&mut written, to3(ring[t[0]], from), to3(ring[t[2]], from), to3(ring[t[1]], from));
630	    }
631	    for i in 0..n {
632	        let j = (i + 1) % n;
633	        let (bi, bj, tj, ti) = (to3(ring[i], from), to3(ring[j], from), to3(ring[j], to), to3(ring[i], to));
634	        tri(&mut written, bi, bj, tj);
635	        tri(&mut written, bi, tj, ti);
636	    }
637	    Some(written)
638	}
639	
640	/// A mesh of triangles as written: their corners listed once, in the order first met.
641	pub fn mesh_of(written: &[[V3; 3]]) -> Mesh {
642	    let mut m = Mesh::default();
643	    for t in written {
644	        let mut idx = [0usize; 3];
645	        for k in 0..3 {
646	            let p = t[k];
647	            idx[k] = match m.points.iter().position(|q| *q == p) {
648	                Some(i) => i,
649	                None => {
650	                    m.points.push(p);
651	                    m.points.len() - 1
652	                }
653	            };
654	        }
655	        m.tris.push(idx);
656	    }
657	    m
658	}
659	
660	/// Mirrors a mesh across its x axis (y to -y), its triangles turned to stay facing out.
661	pub fn mirror_y(m: &mut Mesh) {
662	    for p in m.points.iter_mut() {
663	        p.y = -p.y;
664	    }
665	    for t in m.tris.iter_mut() {
666	        t.swap(1, 2);
667	    }
668	}
