#!/usr/bin/env python3
"""csg.js (Evan Wallace's BSP CSG) in Python, with knobs for the variants an implementation
might differ in; used to match the original's family voids."""
import math, re, sys, itertools

EPS = 1e-5
OPT = {
    'plane_recompute': True,   # a split polygon's plane from its own first three vertices
    'unit_recip': False,       # normalise as v * (1 / len) instead of v / len
}

class V:
    __slots__ = ('x', 'y', 'z')
    def __init__(s, x, y, z):
        s.x, s.y, s.z = x, y, z
    def __add__(s, o): return V(s.x + o.x, s.y + o.y, s.z + o.z)
    def __sub__(s, o): return V(s.x - o.x, s.y - o.y, s.z - o.z)
    def __mul__(s, k): return V(s.x * k, s.y * k, s.z * k)
    def neg(s): return V(-s.x, -s.y, -s.z)
    def dot(s, o): return s.x * o.x + s.y * o.y + s.z * o.z
    def cross(s, o): return V(s.y * o.z - s.z * o.y, s.z * o.x - s.x * o.z, s.x * o.y - s.y * o.x)
    def length(s): return math.sqrt(s.dot(s))
    def unit(s):
        l = s.length()
        if OPT['unit_recip']:
            r = 1.0 / l
            return V(s.x * r, s.y * r, s.z * r)
        return V(s.x / l, s.y / l, s.z / l)
    def lerp(s, o, t): return s + (o - s) * t
    def key(s): return (s.x, s.y, s.z)
    def __repr__(s): return '(%r,%r,%r)' % (s.x, s.y, s.z)

class Plane:
    __slots__ = ('n', 'w')
    def __init__(s, n, w):
        s.n, s.w = n, w
    @staticmethod
    def from_points(a, b, c):
        n = (b - a).cross(c - a).unit()
        return Plane(n, n.dot(a))
    def clone(s): return Plane(s.n, s.w)
    def flip(s):
        s.n = s.n.neg()
        s.w = -s.w
    def split(s, poly, cf, cb, front, back):
        COP, FR, BK, SP = 0, 1, 2, 3
        ptype = 0
        types = []
        for v in poly.verts:
            t = s.n.dot(v) - s.w
            ty = BK if t < -EPS else (FR if t > EPS else COP)
            ptype |= ty
            types.append(ty)
        if ptype == COP:
            (cf if s.n.dot(poly.plane.n) > 0 else cb).append(poly)
        elif ptype == FR:
            front.append(poly)
        elif ptype == BK:
            back.append(poly)
        else:
            f, b = [], []
            n = len(poly.verts)
            for i in range(n):
                j = (i + 1) % n
                ti, tj = types[i], types[j]
                vi, vj = poly.verts[i], poly.verts[j]
                if ti != BK:
                    f.append(vi)
                if ti != FR:
                    b.append(vi)
                if (ti | tj) == SP:
                    t = (s.w - s.n.dot(vi)) / s.n.dot(vj - vi)
                    v = vi.lerp(vj, t)
                    f.append(v)
                    b.append(v)
            if len(f) >= 3:
                front.append(Poly(f, poly.plane))
            if len(b) >= 3:
                back.append(Poly(b, poly.plane))

class Poly:
    __slots__ = ('verts', 'plane')
    def __init__(s, verts, plane=None):
        s.verts = verts
        if plane is None or OPT['plane_recompute']:
            s.plane = Plane.from_points(verts[0], verts[1], verts[2])
        else:
            s.plane = plane.clone()
    def clone(s):
        p = Poly.__new__(Poly)
        p.verts = list(s.verts)
        p.plane = s.plane.clone()
        return p
    def flip(s):
        s.verts.reverse()
        s.plane.flip()

class Node:
    def __init__(s, polys=None):
        s.plane = None
        s.front = None
        s.back = None
        s.polys = []
        if polys:
            s.build(polys)
    def invert(s):
        for p in s.polys:
            p.flip()
        s.plane.flip()
        if s.front:
            s.front.invert()
        if s.back:
            s.back.invert()
        s.front, s.back = s.back, s.front
    def clip_polys(s, polys):
        if s.plane is None:
            return list(polys)
        front, back = [], []
        for p in polys:
            s.plane.split(p, front, back, front, back)
        if s.front:
            front = s.front.clip_polys(front)
        if s.back:
            back = s.back.clip_polys(back)
        else:
            back = []
        return front + back
    def clip_to(s, bsp):
        s.polys = bsp.clip_polys(s.polys)
        if s.front:
            s.front.clip_to(bsp)
        if s.back:
            s.back.clip_to(bsp)
    def all_polys(s):
        out = list(s.polys)
        if s.front:
            out += s.front.all_polys()
        if s.back:
            out += s.back.all_polys()
        return out
    def build(s, polys):
        if not polys:
            return
        if s.plane is None:
            s.plane = polys[0].plane.clone()
        front, back = [], []
        for p in polys:
            s.plane.split(p, s.polys, s.polys, front, back)
        if front:
            if s.front is None:
                s.front = Node()
            s.front.build(front)
        if back:
            if s.back is None:
                s.back = Node()
            s.back.build(back)

def subtract(apolys, bpolys):
    a = Node([p.clone() for p in apolys])
    b = Node([p.clone() for p in bpolys])
    a.invert()
    a.clip_to(b)
    b.clip_to(a)
    b.invert()
    b.clip_to(a)
    b.invert()
    a.build(b.all_polys())
    a.invert()
    return a.all_polys()

def prism_polys(ring, h0, h1, plane='xy', cap_order='top_bottom', bottom_rev='rev'):
    def to3(p, h):
        if plane == 'xz':
            return V(p[0], h, p[1])
        if plane == 'yz':
            return V(h, p[0], p[1])
        return V(p[0], p[1], h)
    n = len(ring)
    top = [to3(p, h1) for p in ring]
    if bottom_rev == 'rev':
        bot = [to3(p, h0) for p in reversed(ring)]
    else:
        bot = [to3(ring[0], h0)] + [to3(p, h0) for p in reversed(ring[1:])]
    sides = []
    for i in range(n):
        j = (i + 1) % n
        sides.append([to3(ring[i], h0), to3(ring[j], h0), to3(ring[j], h1), to3(ring[i], h1)])
    if plane == 'xz':
        top = top[::-1]
        bot = bot[::-1]
        sides = [s[::-1] for s in sides]
    if cap_order == 'top_bottom':
        polys = [top, bot] + sides
    elif cap_order == 'bottom_top':
        polys = [bot, top] + sides
    else:
        polys = sides + [top, bot]
    return [Poly(p) for p in polys]

def circle(cx, cy, r, k=32):
    return [(cx + r * math.cos(2 * math.pi * i / k), cy + r * math.sin(2 * math.pi * i / k)) for i in range(k)]

def triangulate(polys):
    pts = []
    index = {}
    tris = []
    for p in polys:
        vs = p.verts
        ids = []
        for v in vs:
            k = v.key()
            if k not in index:
                index[k] = len(pts)
                pts.append(v)
            ids.append(index[k])
        for i in range(1, len(vs) - 1):
            tris.append((ids[0], ids[i], ids[i + 1]))
    return pts, tris

def fmt(v):
    v = v + 0.0
    return ('%.6f' % v).rstrip('0')

def load_orig(path):
    s = open(path).read().split('\n')
    pts = re.findall(r'\(([-\d.]+),([-\d.]+),([-\d.]+)\)', s[0])
    tris = re.findall(r'\((\d+),(\d+),(\d+)\)', s[1])
    return [tuple(p) for p in pts], [tuple(int(x) - 1 for x in t) for t in tris]

#!/usr/bin/env python3
"""csg.js on the written triangles of the inspection box's forms."""
import itertools, sys, math
sys.path.insert(0, '/tmp/ifc-export-agent/csg')
import csg

def ear_clip(ring):
    n = len(ring)
    idx = list(range(n))
    out = []
    k = 0
    guard = 0
    def cross(a, b): return a[0] * b[1] - a[1] * b[0]
    def sub(a, b): return (a[0] - b[0], a[1] - b[1])
    def in_tri(p, a, b, c):
        d1 = cross(sub(b, a), sub(p, a)); d2 = cross(sub(c, b), sub(p, b)); d3 = cross(sub(a, c), sub(p, c))
        return d1 >= 0 and d2 >= 0 and d3 >= 0
    while len(idx) >= 3 and guard < 10 * n * n + 10:
        guard += 1
        m = len(idx)
        i0, i1, i2 = idx[(k + m - 1) % m], idx[k % m], idx[(k + 1) % m]
        a, b, c = ring[i0], ring[i1], ring[i2]
        convex = cross(sub(b, a), sub(c, b)) > 0
        ok = convex or m == 3
        if ok and m > 3:
            for j in idx:
                if j in (i0, i1, i2):
                    continue
                if in_tri(ring[j], a, b, c):
                    ok = False
                    break
        if ok:
            out.append((i0, i1, i2))
            idx.pop(k % m)
            if k >= len(idx):
                k = 0
        else:
            k = (k + 1) % m
    return out

def written(ring, h0, h1, plane='xy'):
    def to3(p, h):
        if plane == 'xz':
            return csg.V(p[0], h, p[1])
        if plane == 'yz':
            return csg.V(h, p[0], p[1])
        return csg.V(p[0], p[1], h)
    flip = plane == 'xz'
    out = []
    def tri(a, b, c):
        out.append([a, c, b] if flip else [a, b, c])
    for t in ear_clip(ring):
        tri(to3(ring[t[0]], h1), to3(ring[t[1]], h1), to3(ring[t[2]], h1))
        tri(to3(ring[t[0]], h0), to3(ring[t[2]], h0), to3(ring[t[1]], h0))
    n = len(ring)
    for i in range(n):
        j = (i + 1) % n
        bi, bj, tj, ti = to3(ring[i], h0), to3(ring[j], h0), to3(ring[j], h1), to3(ring[i], h1)
        tri(bi, bj, tj)
        tri(bi, tj, ti)
    return out

if __name__ == '__main__':
    orig_pts, orig_tris = csg.load_orig('/tmp/ifc-export-agent/csg/inspection.txt')
    for pr, ur in itertools.product([True, False], [False, True]):
        csg.OPT['plane_recompute'] = pr
        csg.OPT['unit_recip'] = ur
        a = [csg.Poly(t) for t in written(csg.circle(0, 0, 125), -300.0, 0.0)]
        b = [csg.Poly(t) for t in written(csg.circle(0, 0, 105), -280.0, 0.0)]
        res = csg.subtract(a, b)
        pts, tris = csg.triangulate(res)
        fp = [tuple(csg.fmt(c) for c in (p.x, p.y, p.z)) for p in pts]
        same_pts = sum(1 for x, y in zip(fp, orig_pts) if x == y)
        same_tris = sum(1 for x, y in zip(tris, orig_tris) if x == y)
        first_bad = next((i for i, (x, y) in enumerate(zip(tris, orig_tris)) if x != y), None)
        print(pr, ur, 'points', len(pts), 'vs', len(orig_pts), 'equal', same_pts, 'tris', len(tris), 'vs', len(orig_tris), 'equal', same_tris, 'first bad', first_bad)

