#!/usr/bin/env python3
"""Variants of the split interpolation, scored by the signs of the drain's points 24 and 42 and
the three-phase outlet's point 90."""
import sys, itertools
sys.path.insert(0, '/tmp/ifc-export-agent/csg')
import csg
from try_inspection2 import written

def triangulate(polys, kf):
    pts, index, tris = [], {}, []
    for p in polys:
        ids = []
        for v in p.verts:
            k = kf(v)
            if k not in index:
                index[k] = len(pts)
                pts.append(v)
            ids.append(index[k])
        for i in range(1, len(ids) - 1):
            tris.append((ids[0], ids[i], ids[i + 1]))
    return pts, tris

VARIANT = {'t': 'csg', 'lerp': 'csg'}
orig_split = csg.Plane.split
def split(s, poly, cf, cb, front, back):
    COP, FR, BK, SP = 0, 1, 2, 3
    ptype = 0
    types, dists = [], []
    for v in poly.verts:
        t = s.n.dot(v) - s.w
        ty = BK if t < -csg.EPS else (FR if t > csg.EPS else COP)
        ptype |= ty
        types.append(ty)
        dists.append(t)
    if ptype == COP:
        (cf if s.n.dot(poly.plane.n) > 0 else cb).append(poly)
    elif ptype == FR:
        front.append(poly)
    elif ptype == BK:
        back.append(poly)
    else:
        f, b = [], []
        n = len(poly.verts)
        for i in range(n):
            j = (i + 1) % n
            ti, tj = types[i], types[j]
            vi, vj = poly.verts[i], poly.verts[j]
            if ti != BK:
                f.append(vi)
            if ti != FR:
                b.append(vi)
            if (ti | tj) == SP:
                if VARIANT['t'] == 'csg':
                    t = (s.w - s.n.dot(vi)) / s.n.dot(vj - vi)
                else:
                    t = dists[i] / (dists[i] - dists[j])
                if VARIANT['lerp'] == 'csg':
                    v = vi + (vj - vi) * t
                elif VARIANT['lerp'] == 'mix':
                    v = vi * (1 - t) + vj * t
                else:
                    v = vj + (vi - vj) * (1 - t)
                f.append(v)
                b.append(v)
        if len(f) >= 3:
            front.append(csg.Poly(f, poly.plane))
        if len(b) >= 3:
            back.append(csg.Poly(b, poly.plane))
csg.Plane.split = split

def fmt(v):
    return csg.fmt(v)

kf = lambda v: tuple(round(c * 1e6) for c in (v.x, v.y, v.z))
for tv, lv, ur in itertools.product(['csg', 'dist'], ['csg', 'mix', 'rev'], [False, True]):
    VARIANT['t'] = tv
    VARIANT['lerp'] = lv
    csg.OPT['unit_recip'] = ur
    box = [(-50.0, -50.0), (50.0, -50.0), (50.0, 50.0), (-50.0, 50.0)]
    a = [csg.Poly(t) for t in written(box, -50.0, 0.0)]
    b = [csg.Poly(t) for t in written(csg.circle(0, 0, 30), -30.0, 0.0)]
    res = csg.subtract(a, b)
    pts, tris = triangulate(res, kf)
    print(tv, lv, ur, len(pts), 'p24', fmt(pts[24].x), fmt(pts[24].y), 'p42', fmt(pts[42].x), fmt(pts[42].y), '(orig: -0. 30. / -30. 0.)')

