    import joinsim as J

def split_by(ring, sidef):
    """split_ring semantics with a side function: (right <= 0 part, left >= 0 part)."""
    n = len(ring)
    right, left = [], []
    for i in range(n):
        p, q = ring[i], ring[(i + 1) % n]
        sp, sq = sidef(p), sidef(q)
        if sp <= 1e-9: right.append(p)
        if sp >= -1e-9: left.append(p)
        if (sp < -1e-9 and sq > 1e-9) or (sp > 1e-9 and sq < -1e-9):
            t = sp / (sp - sq)
            x = J.add(p, J.mul(J.sub(q, p), t))
            right.append(x); left.append(x)
    return right, left

def cut(ring, pieces, join, piece_mode, join_mode):
    parts, left = [], [ring]
    for i, piece in enumerate(pieces):
        nxt = []
        for r in left:
            rest = r
            m = len(piece)
            for k in range(m):
                a = piece[k]; d = J.sub(piece[(k + 1) % m], a)
                sf = J.line_side(a, d)
                if piece_mode == 'sh':
                    out = J.half(rest, sf, False); inn = J.half(rest, sf, True)
                else:
                    out, inn = split_by(rest, sf)
                if J.ok(out): nxt.append(out)
                rest = inn
                if not J.ok(rest): break
            if J.ok(rest):
                jf = join(i)
                if join_mode == 'sh':
                    rest = J.half(rest, jf, False)
                else:
                    rest = split_by(rest, jf)[0]
                if not J.ok(rest): continue
                parts.append((i, rest))
        left = nxt
    parts.extend((None, r) for r in left)
    return parts

