#!/usr/bin/env python3
"""Random fractional arc walls: which centre formula gives the original's axis points."""
import re, math, json, subprocess, random, sys
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 7)
walls = []
for k in range(40):
    a = (round(random.uniform(-9000, 9000), 3), round(random.uniform(-9000, 9000), 3))
    b = (round(a[0] + random.uniform(-7000, 7000), 3), round(a[1] + random.uniform(-7000, 7000), 3))
    arc = random.choice([1, -1]) * round(random.uniform(5, 300), 2)
    walls.append((a, b, arc))
D = '/tmp/ifc-export-agent/probe'
cmds = ['wall ' + json.dumps({"points": [[a[0], a[1] + 40000 * k], [b[0], b[1] + 40000 * k]], "arc": arc}) for k, (a, b, arc) in enumerate(walls)]
open(D + '/arcax2.txt', 'w').write('\n'.join(cmds) + '\n')
p = subprocess.run(['/workspace/executable', 'run', '--script', D + '/arcax2.txt', '--save', D + '/arcax2.ifc'], capture_output=True, text=True)
if p.returncode:
    print(p.stderr); sys.exit(1)
s = open(D + '/arcax2.ifc').read()
ents = {int(m.group(1)): m.group(2) for m in re.finditer(r'^#(\d+)=\w+\((.*)\);$', s, re.M)}
axes = re.findall(r"IFCSHAPEREPRESENTATION\(#6,'Axis','Curve2D',\(#(\d+)\)\)", s)
ALL = [[ents[int(i)] for i in re.findall(r'#(\d+)', ents[int(a)])] for a in axes]
print('walls', len(ALL))
def fmt(v):
    v = v + 0.0
    return ('%.6f' % v).rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
def perp(v): return (-v[1], v[0])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def rot(v, ang):
    s, c = math.sin(ang), math.cos(ang)
    return (v[0] * c - v[1] * s, v[0] * s + v[1] * c)
def segs(radius, sweep):
    r = abs(radius)
    if r <= 0.5: return 1
    step = 2.0 * math.acos(1.0 - 1.0 / r)
    return max(1, math.ceil(abs(sweep) / step))
def pts(hc, start, end, arc):
    sweep = math.radians(arc)
    chord = sub(end, start)
    c = math.sqrt(chord[0] ** 2 + chord[1] ** 2)
    d = norm(chord)
    R = c / (2.0 * math.sin(abs(sweep) / 2.0))
    if hc == 'C1':
        t = rot(d, -sweep / 2.0); n = perp(t)
        centre = add(start, mul(n, R)) if sweep > 0 else sub(start, mul(n, R))
    elif hc == 'C3':
        m = mul(add(start, end), 0.5); h = (c / 2.0) / math.tan(sweep / 2.0); centre = add(m, mul(perp(d), h))
    elif hc == 'C4':
        m = add(start, mul(chord, 0.5)); h = (c / 2.0) / math.tan(sweep / 2.0); centre = add(m, mul(perp(d), h))
    elif hc == 'C5':
        m = add(mul(start, 0.5), mul(end, 0.5)); h = (c / 2.0) / math.tan(sweep / 2.0); centre = add(m, mul(perp(d), h))
    elif hc == 'C7':
        m = mul(add(start, end), 0.5); h = R * math.cos(sweep / 2.0) * (1 if sweep > 0 else -1); centre = add(m, mul(perp(d), h))
    elif hc == 'C8':
        m = mul(add(start, end), 0.5); h = math.sqrt(max(R * R - c * c / 4, 0))
        h = h if abs(sweep) < math.pi else -h
        h = h if sweep > 0 else -h
        centre = add(m, mul(perp(d), h))
    elif hc == 'C9':
        m = mul(add(start, end), 0.5); h = (c / 2.0) / math.tan(sweep / 2.0)
        pd = perp(chord); pd = mul(pd, 1.0 / c); centre = add(m, mul(pd, h))
    a0 = math.atan2(start[1] - centre[1], start[0] - centre[0])
    dd = (-math.sin(a0), math.cos(a0)) if sweep > 0 else (math.sin(a0), -math.cos(a0))
    nn = perp(dd)
    k = segs(R, sweep)
    out = []
    for i in range(k + 1):
        ang = a0 + sweep * i / k
        p = add(centre, mul((math.cos(ang), math.sin(ang)), R))
        l = (dot(sub(p, start), dd), dot(sub(p, start), nn))
        out.append('(%s,%s)' % (fmt(l[0]), fmt(l[1])))
    return out
for hc in ['C1', 'C3', 'C4', 'C5', 'C7', 'C8', 'C9']:
    tot = ok = 0; bad = []
    for kk, (a, b, arc) in enumerate(walls):
