            faces.push(self.face(&[b[i], b[j], t[j], t[i]]));
        }
        let shell = self.add(format!("IFCCLOSEDSHELL(({}))", refs(&faces)));
        self.add(format!("IFCFACETEDBREP(#{})", shell))
    }

