#!/usr/bin/env python3
"""Top of a sloped floor from its bottom plane (an offset of the top's) plus the plumb thickness:
residue forms, against the original's signs at the tail corners."""
import json, math, itertools
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
obs = []
for r in json.load(open('/tmp/ifc-export-agent/probe/slprobe2.json')):
    fam, x, y, L, W, s, A = r['f']
    obs.append(((float(x), float(y) + W / 2), (float(x) + A, float(y) + W / 2), float(s), 0.0, r['top'], [(float(x), float(y)), (float(x) + L, float(y)), (float(x) + L, float(y) + W), (float(x), float(y) + W)]))
for it in json.load(open('/tmp/ifc-export-agent/probe/slprobe.json')):
    f = it['floor']
    (tx, ty), (hx, hy) = f['arrow']
    obs.append(((float(tx), float(ty)), (float(hx), float(hy)), float(f['slope']), float(f.get('offset', 0.0)), it['top'], [tuple(map(float, p)) for p in f['boundary']]))
print('floors', len(obs))
def n3(x, y, z):
    l = math.sqrt(x * x + y * y + z * z); r = 1.0 / l
    return (x * r, y * r, z * r)
def norm2(x, y):
    l = math.sqrt(x * x + y * y); r = 1.0 / l
    return (x * r, y * r)
T = 200.0
def variants(tail, head, s, z0):
    r = math.radians(s)
    tn, sn, cs = math.tan(r), math.sin(r), math.cos(r)
    u = norm2(head[0] - tail[0], head[1] - tail[1])
    tv = T / cs
    V = {}
    normals = {'sc': (-u[0] * sn, -u[1] * sn, cs), 't1u': n3(-u[0] * tn, -u[1] * tn, 1.0), 'scu': n3(-u[0] * sn, -u[1] * sn, cs)}
    for nm, n in normals.items():
        d = n[0] * tail[0] + n[1] * tail[1] + n[2] * z0
        for dm, db in [('d-t', d - T), ('d-tvnz', d - tv * n[2]), ('d-t*nz', d - T * n[2])]:
            for ev in ['a', 'b']:
                for tm in ['tv', 't/nz', 'T/cs']:
                    def f(p, n=n, db=db, ev=ev, tm=tm, d=d):
                        if ev == 'a':
                            bot = (db - n[0] * p[0] - n[1] * p[1]) / n[2]
                        else:
                            bot = (db - (n[0] * p[0] + n[1] * p[1])) / n[2]
                        if tm == 'tv':
                            return bot + tv
                        if tm == 't/nz':
                            return bot + T / n[2]
                        return bot + T / cs
                    V['%s %s %s %s' % (nm, dm, ev, tm)] = f
    # relative forms: bottom at tail z0 - tv
    V['rel bot+tv'] = lambda p: ((z0 - tv) + ((p[0] - tail[0]) * u[0] + (p[1] - tail[1]) * u[1]) * tn) + tv
    return V
stats = {}
