fn bbox(r: &[V2]) -> (V2, V2) {
    let mut lo = v2(f64::INFINITY, f64::INFINITY);
    let mut hi = v2(f64::NEG_INFINITY, f64::NEG_INFINITY);
    for p in r {
        lo = v2(lo.x.min(p.x), lo.y.min(p.y));
        hi = v2(hi.x.max(p.x), hi.y.max(p.y));
    }
    (lo, hi)
}

/// A ring split by the line through `a` along `d`: the part to its right (outside, for a hole
/// running counter-clockwise) and the part to its left, each walked from the ring's start.
pub fn split_ring(ring: &[V2], a: V2, d: V2) -> (Vec<V2>, Vec<V2>) {
    let n = ring.len();
    let side = |p: V2| d.cross(p - a);
    let mut right = Vec::new();
    let mut left = Vec::new();
    for i in 0..n {
        let p = ring[i];
        let q = ring[(i + 1) % n];
        let sp = side(p);
        let sq = side(q);
        if sp <= 1e-9 {
            right.push(p);
        }
        if sp >= -1e-9 {
            left.push(p);
        }
        if (sp < -1e-9 && sq > 1e-9) || (sp > 1e-9 && sq < -1e-9) {
            let t = sp / (sp - sq);
            let x = p + (q - p) * t;
            right.push(x);
            left.push(x);
        }
    }
    (right, left)
}

/// A face less the openings that reach it: split along each opening's edges in turn, the
/// parts outside each kept, what lies inside them all left out.
pub fn less_openings(ring: &[V2], openings: &[Vec<V2>]) -> Vec<Vec<V2>> {
    if std::env::var("OLD_LESS").is_err() {
        return super::slabs::convex_pieces(ring, openings);
    }
    let mut cur = vec![ring.to_vec()];
    for o in openings {
        let (olo, ohi) = bbox(o);
        let mut hole = o.clone();
        if signed_area(&hole) < 0.0 {
            hole.reverse();
        }
        let mut next = Vec::new();
        for r in cur {
            let (lo, hi) = bbox(&r);
            if ohi.x < lo.x || olo.x > hi.x || ohi.y < lo.y || olo.y > hi.y {
                next.push(r);
                continue;
            }
            let mut rest = r;
            for k in 0..hole.len() {
                let a = hole[k];
                let d = hole[(k + 1) % hole.len()] - a;
                let (outside, inside) = split_ring(&rest, a, d);
                if outside.len() >= 3 && signed_area(&outside).abs() > 1e-6 {
                    next.push(outside);
                }
                rest = inside;
                if rest.len() < 3 || signed_area(&rest).abs() <= 1e-6 {
                    break;
                }
            }
        }
        cur = next;
    }
    cur
}

