#!/usr/bin/env python3
"""Float candidates for a near-rectangle's second ridge node against the original's."""
import json, sys, math
d = json.load(open(sys.argv[1]))
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
def vel(n1, n2, w1=1.0, w2=1.0):
    det = n1[0] * n2[1] - n1[1] * n2[0]
    return ((w1 * n2[1] - w2 * n1[1]) / det, (n1[0] * w2 - n2[0] * w1) / det)
score = {}
for idx, item in enumerate(d):
    b = [tuple(map(float, p)) for p in item['roof']['boundary']]
    n = len(b)
    E = []
    for i in range(n):
        a, c = b[i], b[(i + 1) % n]
        dd = norm((c[0] - a[0], c[1] - a[1]))
        E.append((a, dd, (-dd[1], dd[0])))
    V = [vel(E[(i - 1) % n][2], E[i][2]) for i in range(n)]
    ev = []
    for i in range(n):
        j = (i + 1) % n
        dd = E[i][1]
        rate = (V[j][0] - V[i][0]) * dd[0] + (V[j][1] - V[i][1]) * dd[1]
        if rate < 0:
            ln = (b[j][0] - b[i][0]) * dd[0] + (b[j][1] - b[i][1]) * dd[1]
            ev.append((ln / (-rate), i, j))
    ev.sort()
    if len(ev) < 2:
        continue
    (tA, iA, jA), (tB, iB, jB) = ev[0], ev[1]
    # original's written skeleton points: from pieces, the non-eave points
    pts = set()
    for pc in item['pieces']:
        for q in pc[2:]:
            x, y, z = q.split(',')
            pts.add((x, y))
    at = lambda k, t: (b[k][0] + V[k][0] * t, b[k][1] + V[k][1] * t)
    cands = {
        'B_i_tB': at(iB, tB), 'B_j_tB': at(jB, tB),
        'B_i_tA': at(iB, tA), 'B_j_tA': at(jB, tA),
        'A_i_tA': at(iA, tA), 'A_j_tA': at(jA, tA),
        'A_i_tB': at(iA, tB), 'A_j_tB': at(jA, tB),
    }
    for k, p in cands.items():
        key = (fmt(p[0]), fmt(p[1]))
        st = score.setdefault(k, [0, 0])
        st[0 if key in pts else 1] += 1
print(score)

