#!/usr/bin/env python3
"""A port of export_skeleton.rs (float for float) with switches, to try variants of the event
handling against the original's ridge nodes (roofprobe JSON)."""
import json, math, sys

EPS = 1e-9

def norm(v):
    l = math.sqrt(v[0] * v[0] + v[1] * v[1]); r = 1.0 / l
    return (v[0] * r, v[1] * r)
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def dist(a, b):
    d = sub(a, b); return math.sqrt(d[0] * d[0] + d[1] * d[1])

class Edge:
    def __init__(s, a, d, w):
        s.a, s.d, s.n, s.w = a, d, (-d[1], d[0]), w
class Vert:
    def __init__(s, p, t0, vel, el, er, prev, nxt, node):
        s.p, s.t0, s.vel, s.el, s.er, s.prev, s.next, s.alive, s.node = p, t0, vel, el, er, prev, nxt, True, node
    def at(s, t):
        return add(s.p, mul(s.vel, t - s.t0))

OPT = {'par': 1e-12, 'pos': 'first', 'tie': 1e-9}

def velocity(e1, e2):
    det = e1.n[0] * e2.n[1] - e1.n[1] * e2.n[0]
    if abs(det) < OPT['par']:
        w = e1.w if e1.w > e2.w else e2.w
        return mul(e1.n, w)
    x = (e1.w * e2.n[1] - e2.w * e1.n[1]) / det
    y = (e1.n[0] * e2.w - e2.n[0] * e1.w) / det
    return (x, y)

def node_at(nodes, p, t):
    for i, n in enumerate(nodes):
        if n[1] > 0.0 and dist(n[0], p) < 1e-6:
            return i
    nodes.append((p, t))
    return len(nodes) - 1

def skeleton(ring):
    n = len(ring)
    edges = []
    for i in range(n):
        a, b = ring[i], ring[(i + 1) % n]
        edges.append(Edge(a, norm(sub(b, a)), 1.0))
    nodes = []
    verts = []
    for i in range(n):
        el, er = (i + n - 1) % n, i
        nodes.append((ring[i], 0.0))
        verts.append(Vert(ring[i], 0.0, velocity(edges[el], edges[er]), el, er, (i + n - 1) % n, (i + 1) % n, i))
    arcs = []
    t_now = 0.0
    events = []
    for guard in range(1000):
        best = None
        for i, v in enumerate(verts):
            if not v.alive: continue
            u = verts[v.next]
            e = edges[v.er]
            rate = dot(sub(u.vel, v.vel), e.d)
            if rate < -EPS:
                ln = dot(sub(u.at(t_now), v.at(t_now)), e.d)
                t = t_now + ln / (-rate)
                if t >= t_now - 1e-9 and (best is None or t < best[0] - OPT['tie']):
                    best = (max(t, t_now), i)
        if best is None: break
        t, i = best
        t_now = t
        j = verts[i].next
        if OPT['pos'] == 'first':
            x = verts[i].at(t)
        elif OPT['pos'] == 'second':
            x = verts[j].at(t)
        else:
            x = mul(add(verts[i].at(t), verts[j].at(t)), 0.5)
        node = node_at(nodes, x, t)
        events.append((t, x, i, j))
        group = [i, j]
        while True:
            pv = verts[group[0]].prev
            if pv in group: break
            if dist(verts[pv].at(t), x) < 1e-6: group.insert(0, pv)
            else: break
        while True:
            nv = verts[group[-1]].next
            if nv in group: break
            if dist(verts[nv].at(t), x) < 1e-6: group.append(nv)
            else: break
        for g in group:
            arcs.append((verts[g].node, node, verts[g].el, verts[g].er))
            verts[g].alive = False
        first, last = group[0], group[-1]
        pv, nv = verts[first].prev, verts[last].next
        if pv == last or (len(group) >= 3 and verts[last].next == first):
            continue
        if pv == nv:
            o = pv
            arcs.append((verts[o].node, node, verts[o].el, verts[o].er))
            verts[o].alive = False
            continue
        el, er = verts[first].el, verts[last].er
        k = len(verts)
        verts.append(Vert(x, t, velocity(edges[el], edges[er]), el, er, pv, nv, node))
        verts[pv].next = k
        verts[nv].prev = k
    return nodes, events

def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')

if __name__ == '__main__':
    d = json.load(open(sys.argv[1]))
    for spec in sys.argv[2:] or ['par=1e-12,pos=first,tie=1e-9']:
        for kv in spec.split(','):
            k, v = kv.split('=')
            OPT[k] = float(v) if k in ('par', 'tie') else v
        ok = bad = 0
        for item in d:
            b = [tuple(map(float, p)) for p in item['roof']['boundary']]
            nodes, events = skeleton(b)
            pts = set()
            for pc in item['pieces']:
                for q in pc[2:]:
                    x, y, z = q.split(',')
                    pts.add((x, y))
            mine = set((fmt(p[0]), fmt(p[1])) for p, t in nodes if t > 0)
            if mine == pts: ok += 1
            else: bad += 1
        print(spec, 'ok', ok, 'bad', bad)

