#!/usr/bin/env python3
"""Eave-corner heights of hip roofs: plane forms that carry the thickness (as sloped floors'
do), against roofprobe JSON files."""
import json, math, sys
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
data = []
for f in sys.argv[1:]:
    data += json.load(open(f))
LEV = {'Level 1': 0.0, 'Level 2': 3000.0}
T = 300.0
stats = {}
first = {}
for item in data:
    r = item['roof']
    lev = LEV[r['level']]
    base = float(r.get('offset', 0.0))
    s = math.radians(r['slope'])
    tn, cs = math.tan(s), math.cos(s)
    tv = T / cs
    for pc in item['pieces']:
        pts = [tuple(map(float, q.split(','))) for q in pc]
        r0, r1 = pts[0][:2], pts[1][:2]
        ex, ey = r1[0] - r0[0], r1[1] - r0[1]
        L = math.sqrt(ex * ex + ey * ey)
        d = (ex * (1.0 / L), ey * (1.0 / L))
        nrm = (-d[1], d[0])
        nx, ny = -nrm[0] * tn, -nrm[1] * tn
        S = lambda p: nx * p[0] + ny * p[1]
        V = {}
        V['cur'] = lambda p: (nx * r0[0] + ny * r0[1] + (lev + base) - S(p)) - lev
        for nm, dd in [('top+tv', nx * r0[0] + ny * r0[1] + lev + (base + tv)),
                       ('top+tv2', nx * r0[0] + ny * r0[1] + (lev + (base + tv))),
                       ('top+tv3', nx * r0[0] + ny * r0[1] + (lev + base + tv)),
                       ('top+tv4', nx * r0[0] + ny * r0[1] + lev + base + tv)]:
            V[nm + ' a'] = (lambda dd: lambda p: ((dd - S(p)) - lev) - tv)(dd)
            V[nm + ' b'] = (lambda dd: lambda p: (dd - S(p)) - (lev + tv))(dd)
            V[nm + ' c'] = (lambda dd: lambda p: (dd - S(p)) - tv - lev)(dd)
        for nm, dd in [('ref1', nx * r1[0] + ny * r1[1] + (lev + base))]:
            V[nm] = (lambda dd: lambda p: (dd - S(p)) - lev)(dd)
        for q in pts[:2]:
            want = fmt(q[2])
            for name, f in V.items():
                got = fmt(f(q[:2]))
                ok = got == want
                st = stats.setdefault(name, [0, 0])
                st[0 if ok else 1] += 1
                if not ok and name not in first:
                    first[name] = (q, want, got)
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-16s ok %4d bad %4d' % (k, v[0], v[1]), first.get(k))

