#!/usr/bin/env python3
"""Hypothesis: the roof's corners are recomputed as crossings of its edges' lines (offset by the
overhang, here 0) before the planes and the skeleton: eave-corner signs against roofprobe."""
import json, math, sys
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
data = []
for f in sys.argv[1:]:
    data += json.load(open(f))
LEV = {'Level 1': 0.0, 'Level 2': 3000.0}
def corners(b, mode):
    n = len(b)
    out = []
    for i in range(n):
        p0, p1, p2 = b[(i - 1) % n], b[i], b[(i + 1) % n]
        if mode == 'none':
            out.append(p1); continue
        if mode.startswith('unit'):
            d1 = norm((p1[0] - p0[0], p1[1] - p0[1])); d2 = norm((p2[0] - p1[0], p2[1] - p1[1]))
        else:
            d1 = (p1[0] - p0[0], p1[1] - p0[1]); d2 = (p2[0] - p1[0], p2[1] - p1[1])
        n1 = (-d1[1], d1[0]); n2 = (-d2[1], d2[0])
        off = 0.0
        a1 = (p0[0] + n1[0] * off, p0[1] + n1[1] * off)
        a2 = (p1[0] + n2[0] * off, p1[1] + n2[1] * off)
        den = cross(d1, d2)
        if mode.endswith('A'):
            t = cross((a2[0] - a1[0], a2[1] - a1[1]), d2) / den
            out.append((a1[0] + d1[0] * t, a1[1] + d1[1] * t))
        else:
            # from the second line
            t = cross((a2[0] - a1[0], a2[1] - a1[1]), d1) / den
            out.append((a2[0] + d2[0] * t, a2[1] + d2[1] * t))
    return out
for mode in ['none', 'unitA', 'unitB', 'rawA', 'rawB']:
    ok = bad = 0
    for item in data:
        r = item['roof']
        lev = LEV[r['level']]
        base = float(r.get('offset', 0.0))
        tn = math.tan(math.radians(r['slope']))
        b = [tuple(map(float, p)) for p in r['boundary']]
        c = corners(b, mode)
        n = len(c)
        for k, pc in enumerate(item['pieces'][:n]):
            r0, r1 = c[k], c[(k + 1) % n]
            d = norm((r1[0] - r0[0], r1[1] - r0[1]))
            nrm = (-d[1], d[0])
            nx, ny = -nrm[0] * tn, -nrm[1] * tn
            dd = nx * r0[0] + ny * r0[1] + (lev + base)
