"""Eave-corner signs: the eave plane anchored at other points than the face's first corner."""
import json, math, sys
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
data = []
for f in sys.argv[1:]:
    data += json.load(open(f))
LEV = {'Level 1': 0.0, 'Level 2': 3000.0}
stats = {}
for item in data:
    r = item['roof']
    lev = LEV[r['level']]
    base = float(r.get('offset', 0.0))
    if base != 0.0:
        continue
    tn = math.tan(math.radians(r['slope']))
    b = [tuple(map(float, p)) for p in r['boundary']]
    n = len(b)
    cx = sum(p[0] for p in b) / n
    cy = sum(p[1] for p in b) / n
    for k, pc in enumerate(item['pieces'][:n]):
        r0, r1 = b[k], b[(k + 1) % n]
        d = norm((r1[0] - r0[0], r1[1] - r0[1]))
        nrm = (-d[1], d[0])
        nx, ny = -nrm[0] * tn, -nrm[1] * tn
        anchors = {
            'r0': r0, 'r1': r1,
            'mid': ((r0[0] + r1[0]) * 0.5, (r0[1] + r1[1]) * 0.5),
            'lerp': (r0[0] + (r1[0] - r0[0]) * 0.5, r0[1] + (r1[1] - r0[1]) * 0.5),
