#!/usr/bin/env python3
"""Count differing tuples between the original's and my export of cases (line by line).
usage: tupdiff.py CASE..."""
import os, re, sys
sys.path.insert(0, '/tmp/ifc-export-agent/tools')
import case
for name in sys.argv[1:]:
    bim = os.path.join(case.D, name + '.bimcraft')
    if not os.path.exists(bim):
        case.build(name)
    a = case.norm(case.export(case.ORIG, bim)[3]).splitlines()
    b = case.norm(case.export(case.MINE, bim)[3]).splitlines()
    if len(a) != len(b):
        print(name, 'line counts differ', len(a), len(b))
        continue
    nd = 0
    ex = []
    for la, lb in zip(a, b):
        if la == lb:
            continue
        ta = re.findall(r'\([^()]*\)', la)
        tb = re.findall(r'\([^()]*\)', lb)
        if len(ta) != len(tb):
            nd += 1000
            continue
        for x, y in zip(ta, tb):
            if x != y:
                nd += 1
                if len(ex) < 4:
                    ex.append((x, y))
    print(name, 'differing tuples', nd, ex)

