        if len(ridge) != len(pc['top']) - 2:
            continue
        cands = {'first': ridge[0], 'last': ridge[-1]}
        if len(ridge) > 1:
            cands['max_t'] = max(ridge, key=lambda q: q[1])
        for cn, (P, t) in cands.items():
