src = open('/tmp/ifc-export-agent/tools/skelpy.py').read().split("if __name__ == '__main__':")[0]
exec(src)
OPT['snap'] = 1e-6
OPT['tie'] = 1e-12
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
d = json.load(open(sys.argv[1]))
stats = {}
for item in d:
    r = item['roof']
    lev, base = 0.0, 0.0
    s = math.radians(r['slope'])
    tn = math.tan(s)
    b = [tuple(map(float, p)) for p in r['boundary']]
    n = len(b)
    nodes, events = skeleton(b)
    for k, pc in enumerate(item['pieces'][:n]):
        r0, r1 = b[k], b[(k + 1) % n]
        ex, ey = r1[0] - r0[0], r1[1] - r0[1]
        L = math.sqrt(ex * ex + ey * ey)
        dvec = (ex * (1.0 / L), ey * (1.0 / L))
        nrm = (-dvec[1], dvec[0])
        nx, ny = -nrm[0] * tn, -nrm[1] * tn
        S = lambda p: nx * p[0] + ny * p[1]
        ridge = []
        for q in pc['top'][2:]:
            x, y, z = q.split(',')
            for (p, t) in nodes:
                if t > 0 and fmt(p[0]) == x and fmt(p[1]) == y:
                    ridge.append((p, t))
                    break
        if len(ridge) != len(pc['top']) - 2:
            continue
        cands = {'first': ridge[0], 'last': ridge[-1]}
        if len(ridge) > 1:
            cands['max_t'] = max(ridge, key=lambda q: q[1])
        for cn, (P, t) in cands.items():
            h = base + t * tn
            for dn in ['A', 'B', 'C']:
                if dn == 'A':
                    dd = S(P) + (lev + h)
                elif dn == 'B':
                    dd = nx * P[0] + ny * P[1] + lev + h
                else:
                    dd = (lev + h) + S(P)
                f = lambda q: (dd - S(q)) - lev
                for q, want in [(r0, pc['bottom'][0]), (r1, pc['bottom'][1])]:
                    ok = fmt(f(q)) == want.split(',')[2]
                    st = stats.setdefault(cn + ' ' + dn, [0, 0])
                    st[0 if ok else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-12s ok %4d bad %4d' % (k, v[0], v[1]))

