#!/usr/bin/env python3
"""Each language's default phases and phase filters, as a new project of it saves them."""
import json, subprocess, os
D = '/tmp/ifc-export-agent/probe/lang'
os.makedirs(D, exist_ok=True)
out = {}
for code in ['en', 'pt', 'es', 'sv', 'cs', 'fr', 'de']:
    open(D + '/l.txt', 'w').write('new {"language": "%s"}\n' % code)
    p = subprocess.run(['/workspace/executable', 'run', '--script', D + '/l.txt', '--save', D + '/l_%s.bimcraft' % code], capture_output=True, text=True)
    d = json.load(open(D + '/l_%s.bimcraft' % code))
    out[code] = {'phases': d.get('phases'), 'phase_filters': d.get('phase_filters'), 'keys': [k for k in d.keys() if 'phase' in k or 'option' in k]}
    print(code, json.dumps(out[code], ensure_ascii=False))

