#!/usr/bin/env python3
"""For each language: a case placing one component of every type of every built-in family
(doors and windows in a wall), x_fam_all_LANG."""
import json, subprocess, os
D = '/tmp/ifc-export-agent/probe/lang'
os.makedirs(D, exist_ok=True)
for code in ['en', 'pt', 'es', 'sv', 'cs', 'fr', 'de']:
    open(D + '/f.txt', 'w').write('new {"language": "%s"}\n' % code)
    subprocess.run(['/workspace/executable', 'run', '--script', D + '/f.txt', '--save', D + '/f_%s.bimcraft' % code], capture_output=True, text=True)
    d = json.load(open(D + '/f_%s.bimcraft' % code))
    fams = d.get('families', {})
    cmds = ['new {"language": "%s"}' % code]
    k = 0
    doors = []
    for name, f in fams.items():
        cat = f.get('category', '')
        types = list((f.get('types') or {}).keys()) or [None]
        for t in types:
            if cat in ('door', 'window'):
                doors.append((name, t, cat))
                continue
            x, y = 3000 * (k % 10), 3000 * (k // 10)
            k += 1
            c = {"family": name, "at": [x, y]}
            if t is not None:
                c["type"] = t
            if k % 3 == 0:
                c["angle"] = 30
            if k % 5 == 0:
                c["mirrored"] = True
            cmds.append('component ' + json.dumps(c, ensure_ascii=False))
    # a long wall for the doors and windows
    y0 = 3000 * (k // 10 + 2)
    n = len(doors)
    cmds.append('wall ' + json.dumps({"points": [[0, y0], [3000 * n + 3000, y0]], "type": None} if False else {"points": [[0, y0], [3000 * n + 3000, y0]]}))
    for i, (name, t, cat) in enumerate(doors):
        c = {"at": [3000 * i + 2000, y0], "family": name}
        if t is not None:
            c["type"] = t
        if i % 2 == 1:
            c["flip_facing"] = True
        if i % 3 == 1:
            c["flip_hand"] = True
        cmds.append(cat + ' ' + json.dumps(c, ensure_ascii=False))
    open('/tmp/ifc-export-agent/cases/x_fam_all_%s.txt' % code, 'w').write('\n'.join(cmds) + '\n')
    print(code, len(cmds), 'commands', len(fams), 'families')

