#!/usr/bin/env python3
"""Level 1 rotated hip roofs: eave planes as unit 3D normals and offsets, several ways."""
import json, math, sys, itertools
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
d = json.load(open(sys.argv[1]))
stats = {}
def n3u(x, y, z):
    l = math.sqrt(x * x + y * y + z * z); r = 1.0 / l
    return (x * r, y * r, z * r)
for item in d:
    r = item['roof']
    lev, base = 0.0, 0.0
    s = math.radians(r['slope'])
    tn, cs, sn = math.tan(s), math.cos(s), math.sin(s)
    b = [tuple(map(float, p)) for p in r['boundary']]
    n = len(b)
    for k, pc in enumerate(item['pieces'][:n]):
        r0, r1 = b[k], b[(k + 1) % n]
        ex, ey = r1[0] - r0[0], r1[1] - r0[1]
        L = math.sqrt(ex * ex + ey * ey)
        dv = (ex * (1.0 / L), ey * (1.0 / L))
        nrm = (-dv[1], dv[0])
        normals = {
            'sc': (-nrm[0] * sn, -nrm[1] * sn, cs),
            'tu': n3u(-nrm[0] * tn, -nrm[1] * tn, 1.0),
            't1': (-nrm[0] * tn, -nrm[1] * tn, 1.0),
