#!/usr/bin/env python3
"""Level 1 rotated hip roofs: each face's plane fitted to its 3D corners (Newell's normal,
through their centroid or a corner), its eave corners' heights re-evaluated."""
import json, math, sys
sys.argv = [sys.argv[0]] + sys.argv[1:]
src = open('/tmp/ifc-export-agent/tools/skelpy.py').read().split("if __name__ == '__main__':")[0]
exec(src)
OPT['snap'] = 1e-6
OPT['tie'] = 1e-12
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
d = json.load(open(sys.argv[1]))
stats = {}
for item in d:
    r = item['roof']
    base = 0.0
    tn = math.tan(math.radians(r['slope']))
    b = [tuple(map(float, p)) for p in r['boundary']]
    n = len(b)
    nodes, events = skeleton(b)
    for k, pc in enumerate(item['pieces'][:n]):
        r0, r1 = b[k], b[(k + 1) % n]
        ridge = []
        for q in pc['top'][2:]:
            x, y, z = q.split(',')
            for (p, t) in nodes:
                if t > 0 and fmt(p[0]) == x and fmt(p[1]) == y:
                    ridge.append((p, t))
                    break
        if len(ridge) != len(pc['top']) - 2:
            continue
        P = [(r0[0], r0[1], base), (r1[0], r1[1], base)] + [(p[0], p[1], base + t * tn) for p, t in ridge]
        m = len(P)
        nxs = nys = nzs = 0.0
        for i in range(m):
            a, c = P[i], P[(i + 1) % m]
            nxs += (a[1] - c[1]) * (a[2] + c[2])
            nys += (a[2] - c[2]) * (a[0] + c[0])
            nzs += (a[0] - c[0]) * (a[1] + c[1])
        for nn, N in [('raw', (nxs, nys, nzs))]:
            cx = sum(p[0] for p in P) / m; cy = sum(p[1] for p in P) / m; cz = sum(p[2] for p in P) / m
            for an, A in [('cent', (cx, cy, cz)), ('p0', P[0]), ('p1', P[1])]:
                dd = N[0] * A[0] + N[1] * A[1] + N[2] * A[2]
                for en in ['a', 'b']:
                    for q, want in [(r0, pc['bottom'][0]), (r1, pc['bottom'][1])]:
                        if en == 'a':
                            z = (dd - N[0] * q[0] - N[1] * q[1]) / N[2]
                        else:
                            z = A[2] - (N[0] * (q[0] - A[0]) + N[1] * (q[1] - A[1])) / N[2]
                        ok = fmt(z) == want.split(',')[2]
                        st = stats.setdefault(nn + ' ' + an + ' ' + en, [0, 0])
                        st[0 if ok else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-14s ok %4d bad %4d' % (k, v[0], v[1]))

