#!/usr/bin/env python3
"""Each door's and window's placement in its wall (the original's) with the wall's location line
and type: to see when its y is written -0.
usage: openy.py CASE..."""
import json, re, sys
for name in sys.argv[1:]:
    D = '/tmp/ifc-export-agent/cases/'
    d = json.load(open(D + name + '.bimcraft'))
    els = d['elements']
    by_guid = {e.get('guid'): (k, e) for k, e in els.items()}
    lib = d.get('library', {})
    gname = {v.get('guid'): v.get('name') for v in lib.values()}
    s = open(D + name + '.ifc').read()
    ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
    def refs(t): return [int(x) for x in re.findall(r'#(\d+)', t)]
    # openings: IFCOPENINGELEMENT placement; the filler's id is its tag
    fills = {}
    for i, (t, a) in ents.items():
        if t == 'IFCRELFILLSELEMENT':
            r = refs(a)
            fills[r[-1]] = r[-2]
    for i, (t, a) in sorted(ents.items()):
        if t in ('IFCDOOR', 'IFCWINDOW'):
            tag = re.findall(r"'(\d{6})'", a)
            op = fills.get(i)
            pl = refs(ents[op][1])[0]
            ax = refs(ents[pl][1])[1]
            pt = ents[refs(ents[ax][1])[0]][1]
            # the element by order: match by GlobalId is hard; use the mark
            mark = re.findall(r",'([^']*)',[0-9.]+,[0-9.]+,\.(?:DOOR|WINDOW)\.", a)
            for k, e in els.items():
                if e.get('category') in ('door', 'window') and e.get('mark') == (mark[0] if mark else None) and t[3:].lower() == e['category']:
                    hk, h = by_guid.get(e.get('host'), (None, {}))
                    print(name, t, 'mark', e.get('mark'), 'host', hk, 'loc', h.get('location'), 'type', gname.get(h.get('type')), 'arc', h.get('arc'), 'placement', pt)

