#!/usr/bin/env python3
"""Hypotheses for the opening placement's y in its wall's axes (its sign when it is zero)."""
import json, re, sys, math
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
stats = {}
for name in sys.argv[1:]:
    D = '/tmp/ifc-export-agent/cases/'
    d = json.load(open(D + name + '.bimcraft'))
    els = d['elements']
    by_guid = {e.get('guid'): (k, e) for k, e in els.items()}
    lib = d.get('library', {})
    gname = {v.get('guid'): v.get('name') for v in lib.values()}
    types = d.get('types', {})
    s = open(D + name + '.ifc').read()
    ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
    def refs(t): return [int(x) for x in re.findall(r'#(\d+)', t)]
    fills = {}
    for i, (t, a) in ents.items():
        if t == 'IFCRELFILLSELEMENT':
            r = refs(a)
            fills[r[-1]] = r[-2]
    for i, (t, a) in sorted(ents.items()):
        if t not in ('IFCDOOR', 'IFCWINDOW'):
            continue
        op = fills.get(i)
        pl = refs(ents[op][1])[0]
        ax = refs(ents[pl][1])[1]
        pt = ents[refs(ents[ax][1])[0]][1].strip('()').split(',')
        mark = re.findall(r",'([^']*)',[0-9.]+,([0-9.]+),\.(?:DOOR|WINDOW)\.", a)
        for k, e in els.items():
            if e.get('category') == t[3:].lower() and e.get('mark') == mark[0][0]:
                hk, h = by_guid.get(e.get('host'), (None, {}))
                if h.get('arc') or h.get('location') not in (None, 'centre'):
                    continue
                ow = float(mark[0][1])
                st, en = h['start'], h['end']
                dv = norm((en[0] - st[0], en[1] - st[1]))
                nv = (-dv[1], dv[0])
                off = e['offset']
                L = math.hypot(en[0] - st[0], en[1] - st[1])
                cands = {}
                for nm, s_ in [('start', off - ow / 2), ('mid', off), ('end', off + ow / 2)]:
                    P = (st[0] + dv[0] * s_, st[1] + dv[1] * s_)
                    v = (P[0] - st[0], P[1] - st[1])
                    cands[nm] = v[0] * nv[0] + v[1] * nv[1]
                    # lerp along the wall
                    t_ = s_ / L
                    P2 = (st[0] + (en[0] - st[0]) * t_, st[1] + (en[1] - st[1]) * t_)
                    v2_ = (P2[0] - st[0], P2[1] - st[1])
                    cands[nm + '_lerp'] = v2_[0] * nv[0] + v2_[1] * nv[1]
                for cn, y in cands.items():
                    ok = fmt(y) == pt[1]
                    stt = stats.setdefault(cn, [0, 0])
                    stt[0 if ok else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-12s ok %3d bad %3d' % (k, v[0], v[1]))

