"""Opening placement y: the world point taken into the wall's axes through an inverted affine
(glam's DAffine3::inverse then transform_point3), against the original's signs."""
import json, re, sys, math
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
def cross(a, b):
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])
def dot(a, b): return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
def mat3_inverse(x, y, z):
    t0 = cross(y, z); t1 = cross(z, x); t2 = cross(x, y)
    det = dot(z, t2)
    inv = 1.0 / det
    # from_cols(t0, t1, t2).transpose() * inv: rows are t0, t1, t2
    return [tuple(c * inv for c in t0), tuple(c * inv for c in t1), tuple(c * inv for c in t2)]  # rows
def mul_rows(rows, v):
    # glam computes M * v as x_axis * v.x + y_axis * v.y + z_axis * v.z (columns)
    cols = [(rows[0][j], rows[1][j], rows[2][j]) for j in range(3)]
    r = (0.0, 0.0, 0.0)
    out = [cols[0][i] * v[0] for i in range(3)]
    out = [out[i] + cols[1][i] * v[1] for i in range(3)]
    out = [out[i] + cols[2][i] * v[2] for i in range(3)]
    return tuple(out)
stats = {}
for name in sys.argv[1:]:
    D = '/tmp/ifc-export-agent/cases/'
    d = json.load(open(D + name + '.bimcraft'))
    els = d['elements']
    by_guid = {e.get('guid'): (k, e) for k, e in els.items()}
    s = open(D + name + '.ifc').read()
    ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
    def refs(t): return [int(x) for x in re.findall(r'#(\d+)', t)]
    fills = {}
    for i, (t, a) in ents.items():
        if t == 'IFCRELFILLSELEMENT':
            r = refs(a)
            fills[r[-1]] = r[-2]
    for i, (t, a) in sorted(ents.items()):
        if t not in ('IFCDOOR', 'IFCWINDOW'):
            continue
        op = fills.get(i)
        pl = refs(ents[op][1])[0]
        ax = refs(ents[pl][1])[1]
        pt = ents[refs(ents[ax][1])[0]][1].strip('()').split(',')
        mark = re.findall(r",'([^']*)',[0-9.]+,([0-9.]+),\.(?:DOOR|WINDOW)\.", a)
        for k, e in els.items():
            if e.get('category') == t[3:].lower() and e.get('mark') == mark[0][0]:
                hk, h = by_guid.get(e.get('host'), (None, {}))
                if h.get('arc') or h.get('location') not in (None, 'centre'):
                    continue
                ow = float(mark[0][1])
                st, en = h['start'], h['end']
                dv = norm((en[0] - st[0], en[1] - st[1]))
                nv = (-dv[1], dv[0])
                off = e['offset']
                X = (dv[0], dv[1], 0.0); Y = (nv[0], nv[1], 0.0); Z = (0.0, 0.0, 1.0)
                # glam: Mat3 from the direction: maybe built as (x, z.cross(x), z)
                Y2 = cross(Z, X)
                cands = {}
                for yn, YY in [('perp', Y), ('zx', Y2)]:
                    inv = mat3_inverse(X, YY, Z)
                    O = (st[0], st[1], 0.0)
                    tinv = mul_rows(inv, O)
                    tinv = (-tinv[0], -tinv[1], -tinv[2])
