#!/usr/bin/env python3
"""Free straight walls: the sign of the axis end point's y in the wall's axes, hypotheses."""
import json, re, sys, math
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm(v):
    l = math.sqrt(v[0] ** 2 + v[1] ** 2); r = 1.0 / l
    return (v[0] * r, v[1] * r)
stats = {}
for name in sys.argv[1:]:
    D = '/tmp/ifc-export-agent/cases/'
    d = json.load(open(D + name + '.bimcraft'))
    els = d['elements']
    s = open(D + name + '.ifc').read()
    ents = {int(m.group(1)): (m.group(2), m.group(3)) for m in re.finditer(r'^#(\d+)=(\w+)\((.*)\);$', s, re.M)}
    def refs(t): return [int(x) for x in re.findall(r'#(\d+)', t)]
    for i, (t, a) in sorted(ents.items()):
        if t != 'IFCWALL':
            continue
        tag = re.findall(r"'(\d{6})',\.STANDARD\.", a)
        e = els[tag[0]]
        if e.get('arc') or e.get('location') not in (None, 'centre'):
            continue
        shape = refs(a)[1]
        reps = refs(ents[shape][1])
        axis = None
        for r in reps:
            if "'Axis'" in ents[r][1]:
                axis = [ents[x][1] for x in refs(ents[refs(ents[r][1])[-1]][1])]
        want = axis[-1].strip('()').split(',')[1]
        st, en = e['start'], e['end']
        ex, ey = en[0] - st[0], en[1] - st[1]
        L = math.sqrt(ex * ex + ey * ey)
        dv = norm((ex, ey))
        nv = (-dv[1], dv[0])
        cands = {}
        P = (st[0] + dv[0] * L, st[1] + dv[1] * L)
        v = (P[0] - st[0], P[1] - st[1])
        cands['start+dL'] = v[0] * nv[0] + v[1] * nv[1]
        v = (en[0] - st[0], en[1] - st[1])
        cands['end'] = v[0] * nv[0] + v[1] * nv[1]
        P = (st[0] + dv[0] * 0.0, st[1] + dv[1] * 0.0)
        P = (P[0] + dv[0] * L, P[1] + dv[1] * L)
        v = (P[0] - st[0], P[1] - st[1])
        cands['(s+d0)+dL'] = v[0] * nv[0] + v[1] * nv[1]
        for cn, y in cands.items():
            ok = fmt(y) == want
            stt = stats.setdefault(cn, [0, 0])
            stt[0 if ok else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-12s ok %3d bad %3d' % (k, v[0], v[1]))

