"""Random floors: polygons convex and not, openings, slopes with arrows, offsets, types:
s_fuzzS."""
import json, math, random, sys
def star_poly(cx, cy, n, rmin, rmax):
    angs = sorted(random.uniform(0, 2 * math.pi) for _ in range(n))
    return [[round(cx + random.uniform(rmin, rmax) * math.cos(a), 1), round(cy + random.uniform(rmin, rmax) * math.sin(a), 1)] for a in angs]
for seed in sys.argv[1:]:
    random.seed(int(seed))
    cmds = []
    for t in [150, 250]:
        cmds.append('type ' + json.dumps({"category": "floor", "name": "F%d" % t, "layers": [{"function": "finish", "material": "Plaster", "thickness": 20}, {"function": "structure", "material": "Concrete", "thickness": t}]}))
    for k in range(24):
        cx, cy = 20000.0 * (k % 6), 20000.0 * (k // 6)
        kind = random.choice(['rect', 'star', 'L'])
        if kind == 'rect':
            w, h = random.uniform(3000, 9000), random.uniform(3000, 7000)
            b = [[cx, cy], [cx + w, cy], [cx + w, cy + h], [cx, cy + h]]
        elif kind == 'L':
            w, h = random.uniform(5000, 9000), random.uniform(5000, 8000)
            b = [[cx, cy], [cx + w, cy], [cx + w, cy + h / 2], [cx + w / 2, cy + h / 2], [cx + w / 2, cy + h], [cx, cy + h]]
        else:
            b = star_poly(cx + 5000, cy + 5000, random.randint(5, 8), 2500, 4500)
        f = {"boundary": [[round(x, 1), round(y, 1)] for x, y in b]}
        if random.random() < 0.5:
            # an opening well inside: a small square near the polygon's first corner, inward
            xs = [p[0] for p in b]; ys = [p[1] for p in b]
            mx, my = sum(xs) / len(xs), sum(ys) / len(ys)
            s = random.uniform(400, 900)
            f["openings"] = [[[round(mx - s, 1), round(my - s, 1)], [round(mx + s, 1), round(my - s, 1)], [round(mx + s, 1), round(my + s, 1)], [round(mx - s, 1), round(my + s, 1)]]]
        if random.random() < 0.5:
            f["slope"] = random.choice([2, 5, 8])
            a = random.uniform(0, 2 * math.pi)
            p0 = b[0]
            f["arrow"] = [[p0[0], p0[1]], [round(p0[0] + 3000 * math.cos(a), 1), round(p0[1] + 3000 * math.sin(a), 1)]]
        if random.random() < 0.4:
            f["offset"] = random.choice([-200, 100, 350])
        if random.random() < 0.5:
            f["type"] = random.choice(["F150", "F250"])
        if random.random() < 0.3:
            f["structural"] = True
        cmds.append('floor ' + json.dumps(f))
    open('/tmp/ifc-export-agent/cases/s_fuzz%s.txt' % seed, 'w').write('\n'.join(cmds) + '\n')
print('ok')

