#!/usr/bin/env python3
"""My ear clipping (export_slabs.rs) in Python, on a ring, printing the triangles."""
import sys, json
def area(r):
    s = 0.0
    for i in range(len(r)):
        a, b = r[i], r[(i + 1) % len(r)]
        s += a[0] * b[1] - b[0] * a[1]
    return s / 2
def cross(u, v): return u[0] * v[1] - u[1] * v[0]
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def in_tri(q, a, b, c, ccw, strict):
    def s(u, v):
        z = cross(sub(v, u), sub(q, u))
        if strict:
            return z > 0 if ccw else z < 0
        return z >= 0 if ccw else z <= 0
    return s(a, b) and s(b, c) and s(c, a)
def ear_clip(ring, strict=False):
    ccw = area(ring) > 0
    idx = list(range(len(ring)))
    out = []
    while len(idx) >= 3:
        m = len(idx)
        found = None
        for i in range(m):
            ip, ic, inx = idx[(i + m - 1) % m], idx[i], idx[(i + 1) % m]
            p, c, n = ring[ip], ring[ic], ring[inx]
            z = cross(sub(c, p), sub(n, c))
            if not (z > 0 if ccw else z < 0):
                continue
            blocked = any(k not in (ip, ic, inx) and in_tri(ring[k], p, c, n, ccw, strict) for k in idx)
            if not blocked:
                found = i
                break
        if found is None:
            break
        i = found
        ip, ic, inx = idx[(i + m - 1) % m], idx[i], idx[(i + 1) % m]
        out.append((ip, ic, inx))
        idx.pop(i)
    return out
ring = json.loads(sys.argv[1])
print('inclusive', ear_clip(ring))
print('strict', ear_clip(ring, True))

