#!/usr/bin/env python3
"""Diagonal-arrow tail corners: variants of the underside-plane formula's sums, against the
original's signs (slprobe4.json), plus the earlier probes to keep."""
import json, math, sys
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
def norm2(x, y):
    l = math.sqrt(x * x + y * y); r = 1.0 / l
    return (x * r, y * r)
T = 200.0
data = []
for it in json.load(open('/tmp/ifc-export-agent/probe/slprobe4.json')):
    f = it['floor']
    lev = 3000.0 if f.get('level') == 'Level 2' else 0.0
    data.append((f, lev, it['top']))
for it in json.load(open('/tmp/ifc-export-agent/probe/slprobe.json')):
    data.append((it['floor'], 0.0, it['top']))
for r in json.load(open('/tmp/ifc-export-agent/probe/slprobe3.json')):
    fam, x, s, elev = r['f']
    if fam == 'bwd':
        arrow = [[x + 4000.0, 2000.0], [float(x), 2000.0]]
    else:
        arrow = [[float(x), 2000.0], [x + 4000.0, 2000.0]]
    f = {"boundary": [[float(x), 0.0], [x + 4000.0, 0.0], [x + 4000.0, 4000.0], [float(x), 4000.0]], "slope": s, "arrow": arrow}
    data.append((f, float(elev), r['top']))
stats = {}
for f, lev, top in data:
    s = math.radians(f['slope'])
    tn, cs = math.tan(s), math.cos(s)
    tv = T / cs
    z0 = float(f.get('offset', 0.0))
    (tx, ty), (hx, hy) = f['arrow']
    tx, ty, hx, hy = map(float, (tx, ty, hx, hy))
    u = norm2(hx - tx, hy - ty)
    nx, ny = -u[0] * tn, -u[1] * tn
    V = {}
    c = z0 - tv
    V['cur'] = (nx * tx + ny * ty + lev + c, lambda p, dd: ((dd - (nx * p[0] + ny * p[1])) - lev) + tv)
    V['a'] = (nx * tx + ny * ty + (lev + c), lambda p, dd: ((dd - (nx * p[0] + ny * p[1])) - lev) + tv)
    V['b'] = (nx * tx + (ny * ty + lev) + c, lambda p, dd: ((dd - (nx * p[0] + ny * p[1])) - lev) + tv)
    V['c'] = (lev + c + nx * tx + ny * ty, lambda p, dd: ((dd - (nx * p[0] + ny * p[1])) - lev) + tv)
    V['d'] = (nx * tx + ny * ty + lev + c, lambda p, dd: ((dd - nx * p[0] - ny * p[1]) - lev) + tv)
    V['e'] = (nx * tx + ny * ty + lev + c, lambda p, dd: (dd - (nx * p[0] + ny * p[1])) - (lev - tv))
    V['f'] = (nx * tx + ny * ty + lev + c, lambda p, dd: (dd - (nx * p[0] + ny * p[1])) + tv - lev)
    V['g'] = ((ny * ty + nx * tx) + lev + c, lambda p, dd: ((dd - (ny * p[1] + nx * p[0])) - lev) + tv)
    for k, p in enumerate(f['boundary']):
        want = top[k].split(',')[2]
        for name, (dd, fn) in V.items():
            got = fmt(fn((float(p[0]), float(p[1])), dd))
            st = stats.setdefault(name, [0, 0])
            st[0 if got == want else 1] += 1
for k, v in sorted(stats.items(), key=lambda kv: kv[1][1]):
    print('%-5s ok %4d bad %4d' % (k, v[0], v[1]))

