#!/usr/bin/env python3
"""Level 1 rotated hip roofs, slope 30: the current eave formula with tan(30) nudged by ulps."""
import json, math, sys
def fmt(x):
    s = '%.6f' % (x + 0.0)
    return s.rstrip('0')
d = json.load(open(sys.argv[1]))
def run(tn):
    ok = bad = 0
    for item in d:
        r = item['roof']
        lev, base = 0.0, 0.0
        b = [tuple(map(float, p)) for p in r['boundary']]
        n = len(b)
        for k, pc in enumerate(item['pieces'][:n]):
            pc = pc['bottom'] if isinstance(pc, dict) else pc
            r0, r1 = b[k], b[(k + 1) % n]
            ex, ey = r1[0] - r0[0], r1[1] - r0[1]
            L = math.sqrt(ex * ex + ey * ey)
            dv = (ex * (1.0 / L), ey * (1.0 / L))
            nrm = (-dv[1], dv[0])
            nx, ny = -nrm[0] * tn, -nrm[1] * tn
            dd = nx * r0[0] + ny * r0[1] + (lev + base)
            for q, want in [(r0, pc[0]), (r1, pc[1])]:
                z = (dd - (nx * q[0] + ny * q[1])) - lev
                if fmt(z) == want.split(',')[2]:
                    ok += 1
                else:
                    bad += 1
    return ok, bad
t = math.tan(math.radians(30))
for k in range(-3, 4):
    tn = t
    if k > 0:
        for _ in range(k): tn = math.nextafter(tn, 1.0)
    elif k < 0:
        for _ in range(-k): tn = math.nextafter(tn, 0.0)
    print(k, repr(tn), run(tn))

