"""Random stairs, ramps and railings: st_fuzzS."""
import json, math, random, sys
for seed in sys.argv[1:]:
    random.seed(int(seed))
    cmds = []
    nid = 100002
    hosts = []
    for k in range(16):
        x0, y0 = 15000.0 * (k % 4), 15000.0 * (k // 4)
        if random.random() < 0.6:
            st = {"start": [x0, y0], "angle": random.choice([0, 30, 90, 135, -45, 180])}
            if random.random() < 0.5:
                st["height"] = random.choice([1500, 2800, 3000, 3600])
            if random.random() < 0.5:
                st["width"] = random.choice([900, 1100, 1300])
            if random.random() < 0.4:
                st["riser"] = random.choice([170, 180, 190])
            if random.random() < 0.4:
                st["tread"] = random.choice([250, 280, 300])
            if random.random() < 0.6:
                n = random.randint(1, 2)
                st["landings"] = [{"at": random.randint(3, 7) + 4 * i, "turn": random.choice([0, 90, -90, 180, -180])} for i in range(n)]
            if random.random() < 0.3:
                st["railings"] = False
            cmds.append('stair ' + json.dumps(st))
        else:
            rp = {"start": [x0, y0], "angle": random.choice([0, 60, 90, -90, 180])}
            rp["height"] = random.choice([300, 450, 900])
            if random.random() < 0.5:
                rp["slope"] = random.choice([5, 6.25, 8.33])
            if random.random() < 0.5:
                rp["landings"] = [{"at": random.choice([150, 300, 450]), "turn": random.choice([0, 90, -90, 180])}]
            if random.random() < 0.5:
                rp["width"] = random.choice([1200, 1500])
            cmds.append('ramp ' + json.dumps(rp))
        hosts.append(nid)
        nid += 1
    for k in range(4):
        x0, y0 = 15000.0 * k, 70000.0
        pts = [[x0, y0]]
        for i in range(random.randint(1, 4)):
            a = random.uniform(0, 2 * math.pi)
            pts.append([round(pts[-1][0] + random.uniform(1000, 4000) * math.cos(a), 1), round(pts[-1][1] + random.uniform(1000, 4000) * math.sin(a), 1)])
        cmds.append('railing ' + json.dumps({"path": pts}))
    open('/tmp/ifc-export-agent/cases/st_fuzz%s.txt' % seed, 'w').write('\n'.join(cmds) + '\n')
print('ok')

